export const mappingColorByMethod = (method: string) => {
  switch (method) {
    case 'POST':
      return '#219342';
    case 'PUT':
      return '#0673C6';
    default:
      return '#DA3E33';
  }
};

export const mappingLabelByMethod = (method: string) => {
  switch (method) {
    case 'POST':
      return 'DC.TxtCreateNew';
    case 'PUT':
      return 'DC.TxtUpdate';
    default:
      return 'DC.TxtDelete';
  }
};
