import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity} from 'react-native';
import styles from './styles';

import {useSafeAreaInsets} from 'react-native-safe-area-context';
import { IcBlackLeftArrow } from '../../../../../assets/images';
import { SizeDP } from '../../../../../constants/Size';
import TextCM from '../../../../../components/Text';
import { View as ViewCM } from 'react-native';
import GroupListCheck from '../../../../../components/GroupListCheck';
import ButtonCM from '../../../../../components/Button';
type ModalTypeSignatureProp = {
  onClose: () => void;
  isVisible: boolean;
  data: any[];
  onSubmit: (item: any[]) => void;
  currentSelected: any[];
};

const ModalTypeSignature = ({
  onClose,
  isVisible,
  data,
  onSubmit,
  currentSelected,
}: ModalTypeSignatureProp) => {
  const {t} = useTranslation();
  const [currentValue, setCurrentValue] = useState(currentSelected);
  const insets = useSafeAreaInsets();

  const hanndleOnpress = (item: any) => {
    if (currentValue.some(i => i.id === item.id)) {
      setCurrentValue(currentValue.filter(i => i.id !== item.id));
    } else {
      setCurrentValue([...currentValue, item]);
    }
  };

  const handleOnsubmit = () => {
    onSubmit(currentValue);
    onClose();
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('GS.addConfigSignature.typeSignature')}
            </TextCM>
            <ViewCM />
          </ViewCM>
          <ViewCM style={styles.viewBody}>
            <TextCM style={styles.txtLabel}>
              {t('GS.addConfigSignature.chooseTypeSignature')}
            </TextCM>
            <GroupListCheck
              data={data}
              onPressData={hanndleOnpress}
              currentValue={currentValue}
              scrollEnabled={true}
            />
            <ButtonCM label={t('CM.BtnConfirm')} onPress={handleOnsubmit} />
          </ViewCM>
        </ViewCM>
      </ViewCM>
    </Modal>
  );
};

export default ModalTypeSignature;
