import {Property} from '.';

export enum LoginType {
  azure = 'azure',
  default = 'default',
  google = 'google',
  twoFactor = 'two-factor',
  twoFactorEmail = 'two-factor-email',
}

enum ConfigProperty {
  RedirectUri = 'redirectUri',
  ClientId = 'clientId',
  TokenUrl = 'tokenUrl',
  AuthorizationUrl = 'authorizationUrl',
  Scope = 'scope',
  ClientSecret = 'clientSecret',
  GrantType = 'grantType',
  Prompt = 'prompt',
  SupportLink = 'supportLink',
  GoogleUserInforUrl = 'userInforUrl',
  GoogleProvider = 'provider',
}

export const getListTypeLogin = () => {
  return [
    {
      id: LoginType.twoFactorEmail,
      label: 'GS.configSecurityLogin.TxtEmailTwoFactorAuth',
    },
    {
      id: LoginType.google,
      label: 'GS.configSecurityLogin.TxtGoogleLogin',
    },
    {
      id: LoginType.twoFactor,
      label: 'GS.configSecurityLogin.TxtGoogleAuthenticatorTwoFactor',
    },
    {
      id: LoginType.azure,
      label: 'GS.configSecurityLogin.TxtAzureTwoFactorAuth',
    },
    {
      id: LoginType.default,
      label: 'GS.configSecurityLogin.TxtDefaultOption',
    },
  ];
};

export const mapDataProperties = (data: any) => {
  const newData: any = {
    redirectUri: data.attrs.redirectUri?.value,
    clientId: data.attrs.clientId?.value,
    tokenUrl: data.attrs.tokenUrl?.value,
    authorizationUrl: data.attrs.authorizationUrl?.value,
    scope: data.attrs.scope?.value,
    clientSecret: data.attrs.clientSecret?.value,
    grantType: data.attrs.grantType?.value,
    prompt: data.attrs.prompt?.value,
    supportLink: data.attrs.supportLink?.value,
  };
  if (data.configType === 'google') {
    newData.userInforUrl = data.attrs.userInforUrl?.value;
    newData.provider = data.attrs.provider?.value;
  }
  return newData;
};

