import {isEmpty} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  Dimensions,
  KeyboardAvoidingView,
  Linking,
  Modal,
  TouchableOpacity,
} from 'react-native';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import PicTypeView from '../PicTypeView';
import {getListItem, getListTypeLogin, mapDataProperties} from './helper';
import styles from './styles';
import {useAppSelector} from '../../../../../hook/useRedux';
import {GroupData} from '../../../../../components/GroupRadio';
import {useGeneralSettingServices} from '../../../../../hook/apiHook/useApi';
import Toast from 'react-native-toast-message';
import {IconBlackLeftArrow} from '../../../../../assets/images';
import {View as ViewCM} from 'react-native';
import {SizeDP} from '../../../../../constants/Size';
import TextCM from '../../../../../components/Text';
import TextFieldCM from '../../../../../components/TextField';
import ButtonCM from '../../../../../components/Button';
import {useGeneralSettingFlowStore} from '../../../store/generalSettingFlowStore';

type Props = {
  isVisible: boolean;
  onClose: () => void;
  onSuccess: () => void;
};

export type Property = {
  redirectUri: string;
  clientId: string;
  tokenUrl: string;
  authorizationUrl: string;
  scope: string;
  clientSecret: string;
  grantType: string;
  prompt: string;
  supportLink: string;
  userInforUrl?: string;
  provider?: string;
};

export enum ConfigProperty {
  RedirectUri = 'redirectUri',
  ClientId = 'clientId',
  TokenUrl = 'tokenUrl',
  AuthorizationUrl = 'authorizationUrl',
  Scope = 'scope',
  ClientSecret = 'clientSecret',
  GrantType = 'grantType',
  Prompt = 'prompt',
  SupportLink = 'supportLink',
  GoogleUserInforUrl = 'userInforUrl',
  GoogleProvider = 'provider',
}

const ModalCreateConfig = ({isVisible, onClose, onSuccess}: Props) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const generalSettingServices = useGeneralSettingServices();

  const account = useAppSelector(state => state.account.dataAccount);
  const {currentEdit} = useGeneralSettingFlowStore();

  const [name, setName] = useState('');
  const [typeLogin, setTypeLogin] = useState<GroupData | undefined>();
  const [listProperties, setListProperties] = useState<any[]>([]);
  const [properties, setProperties] = useState<Property | null>(null);

  useEffect(() => {
    getListProperties();
  }, []);

  useEffect(() => {
    getInitData();
  }, []);

  const getInitData = () => {
    if (!currentEdit) return;
    setName(currentEdit?.name);
    setTypeLogin(getListTypeLogin().find(item => item.id === currentEdit.type));

    const transformObjectValues = (obj: any) => {
      return Object.keys(obj).reduce((acc: {[key: string]: any}, key) => {
        acc[key] = {value: obj[key]};
        return acc;
      }, {});
    };
    if (!isEmpty(currentEdit.attribute)) {
      setProperties(
        mapDataProperties({
          ...currentEdit,
          attrs: transformObjectValues(currentEdit.attribute),
          configType: currentEdit.type,
        }),
      );
    }
  };

  const updateCurrentProperties = (type = typeLogin) => {
    const data = listProperties.find(item => item.configType === type?.id);
    if (!isEmpty(data?.attrs)) {
      setProperties(mapDataProperties(data));
    } else {
      setProperties(null);
    }
  };

  const getListProperties = async () => {
    const res = await generalSettingServices.listListProperties();

    const current = res.find(
      (item: any) => item.configType === currentEdit?.type,
    );

    if (!isEmpty(current?.attrs)) {
      onChangeValue(
        ConfigProperty.SupportLink,
        current.attrs.supportLink?.value,
      );
    }
    setListProperties(res);
  };

  const onPressSave = async () => {
    const body: any = {
      active: true,
      attribute: null,
      createdBy: account.email,
      createdDate: Date.now(),
      custId: account.custId,
      id: null,
      lastModifiedBy: null,
      lastModifiedDate: null,
      name: name.trim(),
      orgIn: null,
      type: typeLogin?.id,
    };
    if (!isEmpty(properties)) {
      const attribute: any = {
        redirectUri: properties.redirectUri,
        clientId: properties.clientId,
        tokenUrl: properties.tokenUrl,
        authorizationUrl: properties.authorizationUrl,
        scope: properties.scope,
        clientSecret: properties.clientSecret,
        grantType: properties.grantType,
        prompt: properties.prompt,
      };
      if (typeLogin?.id === 'google') {
        attribute.userInforUrl = properties.userInforUrl;
        attribute.provider = properties.provider;
      }
      body.attribute = attribute;
    }

    try {
      if (isEmpty(currentEdit)) {
        await generalSettingServices.createConfigSecurityLogin(body);
      } else {
        await generalSettingServices.updateConfigSecurityLogin({
          ...currentEdit,
          name: name.trim(),
          type: typeLogin?.id,
          attribute: body.attribute,
          active: true,
        });
      }
      onSuccess();
      Toast.show({
        text1: t('GS.configSecurityLogin.TxtCreateSuccess'),
        type: 'success',
      });
    } catch (error) {
      Toast.show({
        text1: t('CM.TxtSystemError'),
        type: 'error',
      });
    } finally {
      onClose();
    }
  };

  const onChangeValue = (type: ConfigProperty, value: string) => {
    setProperties(
      prev =>
        ({
          ...prev,
          [type]: value,
        } as Property),
    );
  };

  const renderContent = () => {
    return (
      <ViewCM
        style={[
          styles.ctnContent,
          {
            paddingBottom: insets.bottom,
            maxHeight: Dimensions.get('screen').height * 0.9,
          },
        ]}>
        <ViewCM style={styles.viewHeader}>
          <TouchableOpacity onPress={onClose}>
            <IconBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
          </TouchableOpacity>
          <TextCM style={styles.txtTitle}>
            {t('GS.configSecurityLogin.TxtConfigLogin')}
          </TextCM>
          <ViewCM />
        </ViewCM>

        <KeyboardAwareScrollView enableAutomaticScroll={!isEmpty(properties)}>
          <ViewCM style={styles.viewBody}>
            <ViewCM style={styles.viewLabel}>
              <TextCM style={styles.txtLabel}>
                {t('GS.configSecurityLogin.TxtConfigLogin')}
              </TextCM>
              <TextCM style={styles.txtDesLabel}>
                {t('GS.configSecurityLogin.TxtTitleConfigLogin')}
              </TextCM>
            </ViewCM>
            <TextFieldCM
              label={t('GS.configSecurityLogin.TxtNameTypeLogin')}
              isRequired
              value={name}
              onChangeText={setName}
              maxLength={249}
            />
            <PicTypeView
              value={typeLogin}
              onPicType={type => {
                setTypeLogin(type);
                updateCurrentProperties(type);
              }}
            />
            {!isEmpty(properties) && (
              <ViewCM style={styles.viewProperties}>
                <TextCM style={styles.txtProperties}>
                  {t('GS.configSecurityLogin.TxtProperties')}
                </TextCM>
                {getListItem(properties, typeLogin?.id as string).map(
                  (item, index) => {
                    if (item.type === ConfigProperty.SupportLink) {
                      return (
                        <ViewCM style={styles.viewSupportLink} key={index}>
                          <TextCM style={styles.txtSupportLink}>
                            {item.label}
                          </TextCM>
                          <TextCM
                            style={styles.txtValueSupportLink}
                            onPress={() =>
                              Linking.openURL(item.value as string)
                            }>
                            {item.value}
                          </TextCM>
                        </ViewCM>
                      );
                    }
                    return (
                      <ViewCM key={index}>
                        <TextFieldCM
                          value={item.value}
                          label={t(item.label)}
                          onChangeText={value => {
                            onChangeValue(item.type, value);
                          }}
                          maxLength={255}
                        />
                      </ViewCM>
                    );
                  },
                )}
              </ViewCM>
            )}
          </ViewCM>
        </KeyboardAwareScrollView>
        <ViewCM style={styles.footer}>
          <ButtonCM
            label={t('CM.TxtSave')}
            disabled={!name.trim() || !typeLogin}
            onPress={onPressSave}
          />
        </ViewCM>
      </ViewCM>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        {isEmpty(properties) ? (
          <KeyboardAvoidingView
            behavior={'padding'}
            keyboardVerticalOffset={-insets.bottom}>
            {renderContent()}
          </KeyboardAvoidingView>
        ) : (
          renderContent()
        )}
      </ViewCM>
    </Modal>
  );
};

export default ModalCreateConfig;
