import {TouchableOpacity} from 'react-native';
import styles from './styles';
import {IcCheckbox, IcCheckboxSelect} from '../../../../../../assets/images';
import TextCM from '../../../../../../components/Text';

interface Props {
  value: boolean;
  onPress?: (value: boolean) => void;
  text: string;
  viewIconRight?: React.ReactNode;
}

const CheckBoxText = ({onPress, value, text, viewIconRight}: Props) => {
  const handleOnPress = () => {
    onPress && onPress(value);
  };
  return (
    <TouchableOpacity style={[styles.viewItem]} onPress={handleOnPress}>
      {value ? (
        <IcCheckboxSelect width={24} height={24} />
      ) : (
        <IcCheckbox width={24} height={24} />
      )}
      <TextCM style={[styles.txtConditional]}>{text}</TextCM>
      {viewIconRight && viewIconRight}
    </TouchableOpacity>
  );
};

export default CheckBoxText;
