import {useRoute} from '@react-navigation/native';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {SafeAreaView} from 'react-native-safe-area-context';
import Header from './components/Header';
import {getTitle, getType} from './helper';
import styles from './styles';
import {ScrollView, TouchableOpacity} from 'react-native';

import {isEmpty} from 'lodash';
import {IExpensesDefault} from '../../../services/interface';
import {useGeneralSettingServices} from '../../../hook/apiHook/useApi';
import TextCM from '../../../components/Text';
import {View as ViewCM} from 'react-native';
import {IconBlueDrag} from '../../../assets/images';
import {ScreenHeight, SizeDP} from '../../../constants/Size';
import Toast from 'react-native-toast-message';
import HeaderCM from '../../../components/Header/HeaderCM';
import ButtonCM from '../../../components/Button';
import DraggableFlatList, {
  RenderItemParams,
  ScaleDecorator,
} from 'react-native-draggable-flatlist';
import {GestureHandlerRootView} from 'react-native-gesture-handler';

export enum FilterType {
  Individual = 'd',
  Company = 'a',
}

const ExpenseDefault = () => {
  const {t} = useTranslation();

  const route = useRoute<any>();
  const type = route.params?.type;

  const generalSettingServices = useGeneralSettingServices();

  const [data, setData] = useState<IExpensesDefault[]>([]);
  const [currentFilter, setCurrentFilter] = useState<{
    label: string;
    id: FilterType;
  }>({
    label: t('GS.expensesDefault.TxtIndividual'),
    id: FilterType.Individual,
  });
  const [isEdit, setIsEdit] = useState(false);

  const toggleEdit = () => {
    setIsEdit(!isEdit);
  };

  useEffect(() => {
    getData();
  }, [currentFilter]);

  const getData = async () => {
    const res = await generalSettingServices.listExpensesDefault({
      type: currentFilter.id,
    });
    setData(
      res
        .filter((item: IExpensesDefault) => item.actionType === getType(type))
        .sort((a, b) => (a.priority || 0) - (b.priority || 0)),
    );
  };
  const renderItem = ({item, drag, isActive}: RenderItemParams<any>) => {
    return (
      <ScaleDecorator>
        <ViewCM style={[styles.item]}>
          {isEdit && (
            <TouchableOpacity onLongPress={drag} disabled={isActive}>
              <IconBlueDrag width={SizeDP(14)} height={SizeDP(24)} />
            </TouchableOpacity>
          )}
          <ViewCM style={styles.viewItemContent}>
            <TextCM style={styles.txtTitleItem}>{item.name}</TextCM>
            <ViewCM style={styles.viewValue}>
              <TextCM style={styles.txtLabel}>
                {t('GS.expensesDefault.TxtID')}
              </TextCM>
              <TextCM style={styles.txtValue} numberOfLines={1}>
                {item.id}
              </TextCM>
            </ViewCM>
            <ViewCM style={styles.viewValue}>
              <TextCM style={styles.txtLabel}>
                {t('GS.expensesDefault.TxtServiceType')}
              </TextCM>
              <TextCM style={styles.txtValue}>{item.serviceType}</TextCM>
            </ViewCM>
          </ViewCM>
        </ViewCM>
      </ScaleDecorator>
    );
  };

  const onPressSave = async () => {
    if (!isEdit) {
      toggleEdit();
      return;
    }
    onUpdateList();
  };

  const onUpdateList = async () => {
    const newData = data.map((item, index) => {
      return {
        ...item,
        id: item.configId,
        type: currentFilter.id,
        priority: index + 1,
      };
    });
    try {
      const res = await generalSettingServices.updateListExpensesDefault(
        newData,
      );
      Toast.show({
        type: 'success',
        text1: t('GS.message.saveSuccess'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    } finally {
      setIsEdit(false);
    }
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM title={getTitle(type, t)} />
      <ViewCM style={styles.body}>
        <GestureHandlerRootView>
          <DraggableFlatList
            ListHeaderComponent={
              <Header
                type={type}
                currentFilter={currentFilter}
                setCurrentFilter={setCurrentFilter}
                showNote={!isEmpty(data)}
              />
            }
            data={data}
            keyExtractor={(item: any) => item.id + item.name}
            renderItem={renderItem}
            contentContainerStyle={{
              flexGrow: 1,
              minHeight: ScreenHeight - SizeDP(200),
            }}
            onDragEnd={({data}) => {
              setData(data);
            }}
            ListEmptyComponent={<Nodata />}
          />
        </GestureHandlerRootView>
      </ViewCM>
      {!isEmpty(data) && (
        <ViewCM style={styles.footer}>
          <ButtonCM
            label={!isEdit ? t('GS.expensesDefault.TxtOrder') : t('CM.TxtSave')}
            onPress={onPressSave}
          />
        </ViewCM>
      )}
    </SafeAreaView>
  );
};

export default ExpenseDefault;

const Nodata = () => {
  const {t} = useTranslation();

  return (
    <TextCM style={styles.txtNoData}>
      {t('GS.expensesDefault.TxtNoExpenses')}
    </TextCM>
  );
};
