import {yupResolver} from '@hookform/resolvers/yup';
import React from 'react';
import {
  Controller,
  FormProvider,
  useForm,
  useFormContext,
} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import * as yup from 'yup';
import styles from './styles';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import TextField from '../../../../../components/TextField';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModalCopyDocumentProp = {
  onClose: () => void;
  isVisible: boolean;
  data: IDocument;
};

const ModalCopyDocument = ({
  data,
  onClose,
  isVisible,
}: ModalCopyDocumentProp) => {
  const {t, i18n} = useTranslation();
  const schema = yup.object().shape({
    text: yup.string().required(i18n.t('SU.fieldRequired')),
  });
  const insets = useSafeAreaInsets();
  const DocumentServices = useDocumentServices();
  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      text: data.name,
    },
  });

  const onSubmit = async () => {
    try {
      const res = await DocumentServices.postCopyEnvelop(
        data?.id,
        methods.getValues('text'),
      );
      Toast.show({
        type: 'success',
        text1: t('DC.copySucessByName', {name: data.name}),
      });
    } catch (error) {
    } finally {
      onClose();
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <View style={styles.ctnContainer}>
          <View style={styles.ctnTop} onTouchEnd={onClose} />
          <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
            <View style={styles.viewHeader}>
              <TouchableOpacity onPress={onClose}>
                <IcBlackLeftArrow width={14} height={16} />
              </TouchableOpacity>
              <TextCM style={styles.txtTitle}>{t('DC.copyDocument')}</TextCM>
              <View />
            </View>
            <View style={styles.viewBody}>
              <FormProvider {...methods}>
                <YupTextField
                  controlName="text"
                  label={t('DC.newNameDocument')}
                />
                <ButtonCM
                  disabled={!methods.formState.isValid}
                  label={t('DC.createCopy')}
                  onPress={onSubmit}
                />
              </FormProvider>
            </View>
          </View>
        </View>
      </KeyboardAvoidingView>
    </Modal>
  );
};

type Props = {
  controlName: string;
  label: string;
  maxLength?: number;
  onPressIconRight?: () => void;
  viewIconRight?: React.ReactNode;
};

const YupTextField = ({
  controlName,
  label,
  maxLength,
  onPressIconRight,
  viewIconRight,
}: Props) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          const handleChangeText = (inputText: string) => {
            if (inputText.startsWith(' ')) {
              inputText = inputText.trimStart();
            }
            onChange(inputText);
          };
          return (
            <TextField
              label={label}
              placeholder={label}
              value={value}
              onBlur={onBlur}
              onChangeText={handleChangeText}
              onIconPress={onPressIconRight}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={viewIconRight}
              isRequired={true}
            />
          );
        }}
      />
    </View>
  );
};
export default ModalCopyDocument;
