import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity, View} from 'react-native';
import styles from './styles';

import ModalListMember from '../ModalListMember';
import GroupRadio, {GroupData} from './components/GroupRadio';
import {
  handleListMemberCanPermit,
  handleListMemberCanPermitDocumentTemplate,
} from './helper';
import {
  IDocument,
  IOrg,
} from '../../../../../../../model/interface/envelope.interface';
import {useDocumentStore} from '../../../../../../../navigation/SideMenu/store/app-store';
import {useDocumentServices} from '../../../../../../../hook/apiHook/useApi';
import {ItemType} from '../../../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {IcBlackLeftArrow} from '../../../../../../../assets/images';
import TextCM from '../../../../../../../components/Text';

type ModalListOrgPermissionProp = {
  onClose: () => void;
  isVisible: boolean;
  data: IOrg[];
  onPress: (data: any[], orgSelected: IOrg) => void;
  dataEnvelope: IDocument;
};

const ModalListOrgPermission = ({
  onClose,
  isVisible,
  data,
  onPress,
  dataEnvelope,
}: ModalListOrgPermissionProp) => {
  const [showModalListMember, setShowModalListMember] = useState(false);
  const [itemSelected, setItemSelected] = useState(data[0]);
  const [loading, setLoading] = useState(false);
  const currentFocused = useDocumentStore(state => state.currentFocused);

  const [listData, setListData] = useState<any>({
    listNotShared: [],
    listShared: [],
  });
  const {t} = useTranslation();
  const DocumentServices = useDocumentServices();
  const hanndleOnpress = (item: GroupData) => {
    const itemSelected = data.find(org => org.orgIn === item.id);
    setItemSelected(itemSelected ?? data[0]);
    toggleModalListMember();
  };

  useEffect(() => {
    getData();
  }, [itemSelected]);

  const getData = async () => {
    try {
      setLoading(true);

      const [resGroupsBelongOrg, resUser, resGroup] = await Promise.all([
        // get toan bo group cua to chuc
        DocumentServices.getGroupBelongOrg(itemSelected?.orgIn),
        // get toan bo user cua to chuc
        DocumentServices.getUserNoSig({
          activated: itemSelected?.activated,
          blocked: itemSelected?.blocked,
          orgIn: itemSelected?.orgIn,
        }),
        // get toan bo group va person da phan quyen cua tai lieu
        DocumentServices.getGroupAclInternal(dataEnvelope.id),
      ]);
      const listUser =
        currentFocused === ItemType.MyDocumentTemplate
          ? handleListMemberCanPermitDocumentTemplate({
              organiztion: itemSelected,
              dataEnvelope: dataEnvelope,
              listUserInOrg: resUser ?? [],
              listGroupInOrg: resGroupsBelongOrg,
              listAllGroupAndPersonShareBelongtoEnvelop: resGroup,
            })
          : handleListMemberCanPermit({
              organiztion: itemSelected,
              dataEnvelope: dataEnvelope,
              listUserInOrg: resUser ?? [],
              listGroupInOrg: resGroupsBelongOrg,
              listAllGroupAndPersonShareBelongtoEnvelop: resGroup,
            });
      setListData(listUser);
    } catch (error) {
    } finally {
      setLoading(false);
    }
  };

  const toggleModalListMember = () => {
    setShowModalListMember(!showModalListMember);
  };

  const onChooseListAclExternal = (array: GroupData[]) => {
    const DataChoose = listData.listNotShared.filter((item: any) =>
      array.some(i => i.id === item.group),
    );
    onPress(DataChoose, itemSelected);
    toggleModalListMember();
    onClose();
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('AI.TxtUnit')}</TextCM>
            <View />
          </View>
          <View style={styles.viewBody}>
            <TextCM style={styles.txtLabel}>
              {t('DC.ShareDocument.chooseUnit')}
            </TextCM>
            <GroupRadio
              data={data.map((item: IOrg) => {
                return {label: item.name, id: item.orgIn};
              })}
              onPressData={hanndleOnpress}
              currentValue={{
                label: itemSelected?.name,
                id: itemSelected?.orgIn,
              }}
              scrollEnabled={true}
            />
          </View>
        </View>
      </View>
      {showModalListMember && (
        <ModalListMember
          onClose={toggleModalListMember}
          isVisible={showModalListMember}
          data={listData.listNotShared.map((item: any) => {
            return {
              label: item?.personal ? `(${item?.personal})` : '',
              id: item.group ?? '',
            };
          })}
          onPress={onChooseListAclExternal}
          loading={loading}
        />
      )}
    </Modal>
  );
};

export default ModalListOrgPermission;
