import React, {useState} from 'react';
import {ScrollView, TouchableOpacity} from 'react-native';

import {useTranslation} from 'react-i18next';
import {SafeAreaView} from 'react-native-safe-area-context';
import {getListGeneralSettings, IGeneralSetting, IMenuItem} from './helper';
import styles from './styles';
import {useNavigation} from '@react-navigation/native';
import { useAppSelector } from '../../../hook/useRedux';
import { NavigationName } from '../../../constants';
import HeaderCM from '../../../components/Header/HeaderCM';
import TextCM from '../../../components/Text';
import { View as ViewCM } from 'react-native';
import { IconBlackDown, IconBlackUp } from '../../../assets/images';
import { SizeDP } from '../../../constants/Size';

const GeneralSetting = () => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();

  const user = useAppSelector(state => state.account.dataAccount);

  const onPressMenuItem = (item: IMenuItem) => {
    switch (item.type) {
      case IGeneralSetting.autoSign:
        navigation.navigate(NavigationName.AutoConfigSignature);
        break;
      case IGeneralSetting.integration:
      case IGeneralSetting.notification:
      case IGeneralSetting.signature:
        navigation.navigate(NavigationName.ExpenseDefaultScreen, {
          type: item.type,
        });
        break;
      case IGeneralSetting.shareTemplate:
        navigation.navigate(NavigationName.ConfigSecurityShareScreen as never);
        break;
      case IGeneralSetting.login:
        navigation.navigate(NavigationName.ConfigSecurityLoginScreen as never);
        break;
      case IGeneralSetting.utility:
        navigation.navigate(NavigationName.AdvancedSettingScreen as never);
        break;
      case IGeneralSetting.password:
        navigation.navigate(
          NavigationName.ConfigSecurityPasswordScreen as never,
        );
        break;
      default:
        break;
    }
  };

  const isAdminRole = () => {
    if (user.authorities && user.authorities.includes('ROLE_ORG_ADMIN')) {
      return true;
    }
    return false;
  };

  const renderListMenu = () => {
    return (
      <ViewCM style={styles.listMenuCtn}>
        {getListGeneralSettings(isAdminRole()).map((item, index) => {
          return (
            <ItemDropDown key={index} data={item} onPress={onPressMenuItem} />
          );
        })}
      </ViewCM>
    );
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM title={t('GS.title')} />
      <ScrollView style={styles.body}>{renderListMenu()}</ScrollView>
    </SafeAreaView>
  );
};

type ItemProps = {
  data: IMenuItem;
  onPress: (type: IMenuItem) => void;
};

const ItemDropDown = ({data, onPress}: ItemProps) => {
  const {t} = useTranslation();
  const [showChild, setshowChild] = useState(false);

  const handleOnpress = () => {
    if (data.listMenu.length > 0 || !data.listMenu) {
      setshowChild(!showChild);
    } else {
      onPress(data);
    }
  };

  return (
    <ViewCM>
      <TouchableOpacity style={styles.viewItem} onPress={handleOnpress}>
        <ViewCM style={styles.itemLabel}>
          <ViewCM style={styles.viewIcon}>{data.icon}</ViewCM>
          <TextCM style={styles.txtItem}>{t(data.label)}</TextCM>
        </ViewCM>
        {data.listMenu.length > 0 &&
          (showChild ? (
            <IconBlackUp width={SizeDP(18)} height={SizeDP(18)} />
          ) : (
            <IconBlackDown width={SizeDP(18)} height={SizeDP(18)} />
          ))}
      </TouchableOpacity>
      <ViewCM style={styles.subViewCtn}>
        {showChild &&
          data.listMenu.map((item, index) => {
            return (
              <ItemDropDown
                key={index}
                data={item}
                onPress={type => {
                  onPress(type);
                }}
              />
            );
          })}
      </ViewCM>
    </ViewCM>
  );
};

export default GeneralSetting;
