
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import styles from './styles';
import { ICustomerConfig } from '../../../model/interface/envelope.interface';
import Toast from 'react-native-toast-message';
import HeaderCM from '../../../components/Header/HeaderCM';
import { IcCheckbox, IcCheckboxSelect, IconBlueBorderShare, IconBluePen } from '../../../assets/images';
import TextCM from '../../../components/Text';
import { View as ViewCM } from 'react-native';
import { SizeDP } from '../../../constants/Size';
import BottomSheetCM from '../../../components/BottomSheet';
import ButtonCM from '../../../components/Button';
import { useGeneralSettingServices } from '../../../hook/apiHook/useApi';

const ConfigSecurityShare = () => {
  const {t} = useTranslation();
  const generalSettingServices = useGeneralSettingServices();

  const [showModalConfig, setShowModalConfig] = useState(false);

  const [data, setData] = useState<ICustomerConfig>();

  const [selected, setSelected] = useState(false);

  const toggleModalConfig = () => {
    setShowModalConfig(!showModalConfig);
  };

  const toggleSelected = () => {
    setSelected(!selected);
  };

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    try {
      const res = await generalSettingServices.getShareConfig();
      setData(res?.[0]);
      setSelected(res?.[0]?.attrs?.same_level?.value);
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      })
    }
  };

  const onSubmit = async () => {
    try {
      (data as ICustomerConfig).attrs.same_level.value = selected;

      const res = await generalSettingServices.putShareConfig(
        data as ICustomerConfig,
      );

      setData(res);
      Toast.show({
        type: 'success',
        text1: t('GS.configSuccess'),
      })
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      })
    } finally {
      toggleModalConfig();
    }
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM
        title={`${t('GS.configSecurity')} - ${t('DC.DocumentTemplate.TxtShare')}`}
      />
      <ViewCM style={styles.body}>
        <ViewCM style={styles.content}>
          <ViewCM style={styles.header}>
            <IconBlueBorderShare width={SizeDP(23)} height={SizeDP(18)} />
            <TextCM style={styles.txtTitle}>{t('GS.shareTemplate')}</TextCM>
          </ViewCM>

          <ViewCM style={styles.item}>
            <TextCM style={styles.txtName}>
              {t('GS.shareConfig.agreeShareTemplateDepartment')}
            </TextCM>
            <ViewCM style={styles.viewAction}>
              <TextCM style={styles.txtEdit}>
                {t('GS.shareConfig.edited')}
              </TextCM>
              <TouchableOpacity
                style={styles.btnEdit}
                onPress={toggleModalConfig}>
                <IconBluePen width={SizeDP(14)} height={SizeDP(14)} />
              </TouchableOpacity>
            </ViewCM>
          </ViewCM>
        </ViewCM>
      </ViewCM>
      {showModalConfig && (
        <BottomSheetCM
          onClose={toggleModalConfig}
          isVisible={showModalConfig}
          title={t('GS.config')}
          renderContent={
            <ViewCM style={styles.modalCtn}>
              <TextCM>{t('GS.shareConfig.agreeShareTemplate')}</TextCM>
              <TouchableOpacity
                style={[styles.viewItem]}
                onPress={toggleSelected}>
                {selected ? (
                  <IcCheckboxSelect width={SizeDP(24)} height={SizeDP(24)} />
                ) : (
                  <IcCheckbox width={SizeDP(24)} height={SizeDP(24)} />
                )}
                <TextCM>{t('GS.shareConfig.agree')}</TextCM>
              </TouchableOpacity>
              <ViewCM>
                <ButtonCM
                  label={t('CM.TxtSave')}
                  onPress={onSubmit}
                  style={{marginTop: SizeDP(16)}}
                />
              </ViewCM>
            </ViewCM>
          }
        />
      )}
    </SafeAreaView>
  );
};

export default ConfigSecurityShare;
