import {isEmpty} from 'lodash';
import React from 'react';
import {useTranslation} from 'react-i18next';
import {Image, TouchableOpacity} from 'react-native';
import styles from './styles';
import ImageCropPicker from '../../../../../components/ImageCropPicker';
import Toast from 'react-native-toast-message';
import TextCM from '../../../../../components/Text';
import { View as ViewCM } from 'react-native';
import { String } from '../../../../../constants';
import { SizeDP } from '../../../../../constants/Size';
import { IconNoImage } from '../../../../../assets/images';

type Prop = {
  data: any;
  onChooseImage: (data: any) => void;
  label?: string;
};

const ChooseImage = ({data, onChooseImage, label}: Prop) => {

  const {t} = useTranslation();

  const onChoiceImage = () => {
    ImageCropPicker.ChoosePhoto({
      includeBase64Enabled: true,
    }).then((res: any) => {
      if (res) {
        if (res.size > 2000000) {
          Toast.show({
            type: 'error',
            text1: t('AC.TxtAlertMaxImageSize'),
          })
        } else {
          onChooseImage(res);
        }
      }
    });
  };

  return (
    <ViewCM style={styles.viewFormPicImage}>
      <ViewCM style={styles.viewImageHeader}>
        <ViewCM style={styles.viewTxtSignatureImage}>
          <TextCM style={styles.txtSignatureImag}>
            {label || t('AC.TxtSignatureImage')}
          </TextCM>
        </ViewCM>
      </ViewCM>
      {!isEmpty(data) ? (
        <ViewCM style={styles.viewImage}>
          <Image
            style={styles.styleImage}
            source={{
              uri: String.PREFIX_IMG_BASE64 + data?.data,
            }}
          />
        </ViewCM>
      ) : (
        <ViewCM style={styles.viewNoImage}>
          <IconNoImage width={SizeDP(60)} height={SizeDP(60)} />
        </ViewCM>
      )}

      <TouchableOpacity style={styles.btnUploadImage} onPress={onChoiceImage}>
        <TextCM style={styles.txtUpload}>
          {isEmpty(data) ? t('AC.uploadImage') : t('AC.TxtReload')}
        </TextCM>
      </TouchableOpacity>
    </ViewCM>
  );
};

export default ChooseImage;
