import React from 'react';
import {useTranslation} from 'react-i18next';
import {Image, Modal, ScrollView, TouchableOpacity} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';

import {IAutoConfigSignType, mappingSignType} from '../../helper';
import {getObjectDiff} from './helper';
import TextCM from '../../../../../components/Text';
import { View as ViewCM } from 'react-native';
import { DateUtils } from '../../../../../utils';
import { IcBlackLeftArrow } from '../../../../../assets/images';
import { SizeDP } from '../../../../../constants/Size';
import ButtonCM from '../../../../../components/Button';
import { IAutoSignProfile, IHistoryAutoSign } from '../../../../../services/interface';

type ModalDetailHistoryProp = {
  onClose: () => void;
  isVisible: boolean;
  type: string;
  data: IHistoryAutoSign;
};

const ModalDetailHistory = ({
  onClose,
  isVisible,
  type,
  data,
}: ModalDetailHistoryProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();

  const renderHistory = () => {
    const listDiffType = getObjectDiff(data.cdc.previousValue, data.cdc.value);

    const listDiffDetailSetting = getObjectDiff(
      data.cdc.previousValue?.signSetting,
      data.cdc.value?.signSetting,
    );

    return (
      <ScrollView style={{flex: 1}} showsVerticalScrollIndicator={false}>
        {type === 'POST' ? (
          <ViewCM>
            <TextCM style={styles.txtLabel}>{t('GS.history.info')}</TextCM>
            <ViewCM style={styles.cardInfo}>
              <ViewCM style={styles.item}>
                <TextCM style={styles.txt400small}>
                  {t('GS.history.name')}
                </TextCM>
                <TextCM style={styles.txt500small}>
                  {data.cdc.value?.personalName}
                </TextCM>
              </ViewCM>
              <ViewCM style={styles.item}>
                <TextCM style={styles.txt400small}>
                  {t('GS.history.email')}
                </TextCM>
                <TextCM style={styles.txt500small}>
                  {data.cdc.value?.email}
                </TextCM>
              </ViewCM>
              <ViewCM style={styles.item}>
                <TextCM style={styles.txt400small}>
                  {t('GS.autoConfig.typeSignature')}
                </TextCM>
                <TextCM style={styles.txt500small}>
                  {data?.cdc.value.signType
                    .map(item => t(mappingSignType(item)))
                    .join(', ')}
                </TextCM>
              </ViewCM>
              <ViewCM style={styles.item}>
                <TextCM style={styles.txt400small}>
                  {t('GS.addConfigSignature.haveCondition')}
                </TextCM>
                <TextCM style={styles.txt500small}>
                  {data.cdc.value?.conditional
                    ? t('GS.history.yes')
                    : t('AI.TxtNo')}
                </TextCM>
              </ViewCM>
              <ViewCM style={styles.item}>
                <TextCM style={styles.txt400small}>
                  {t('GS.history.config')}
                </TextCM>
                <TextCM style={styles.txt500small}>---</TextCM>
              </ViewCM>
              <ViewCM style={styles.item}>
                <TextCM style={styles.txt400small}>
                  {t('GS.autoConfig.status')}
                </TextCM>
                <TextCM style={styles.txt500small}>
                  {data.cdc?.value.active
                    ? t('GS.history.active')
                    : t('GS.history.nonActive')}
                </TextCM>
              </ViewCM>
              <ViewCM style={styles.item}>
                <TextCM style={styles.txt400small}>
                  {t('GS.autoConfig.createDay')}
                </TextCM>
                <TextCM style={styles.txt500small}>
                  {DateUtils.convertDateToDDMMYYYYhhmm(
                    data.cdc.value?.lastModifiedDate?.replace(/\[.*\]$/, '') ??
                      '',
                  )}
                </TextCM>
              </ViewCM>
            </ViewCM>
          </ViewCM>
        ) : (
          <ViewCM style={styles.diffCtn}>
            <DiffItem
              label={t('GS.history.oldInfo')}
              listDiffType={listDiffType}
              listDiffDetailSetting={listDiffDetailSetting}
              data={data?.cdc?.previousValue}
            />
            <DiffItem
              label={t('GS.history.newInfo')}
              listDiffType={listDiffType}
              listDiffDetailSetting={listDiffDetailSetting}
              data={data?.cdc?.value}
            />
          </ViewCM>
        )}
      </ScrollView>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('GS.history.detailHistory')}
            </TextCM>
            <ViewCM />
          </ViewCM>
          <ViewCM style={styles.viewBody}>
            {renderHistory()}
            <ButtonCM onPress={onClose} label={t('CM.BtnClose')} />
          </ViewCM>
        </ViewCM>
      </ViewCM>
    </Modal>
  );
};

const DiffItem = ({
  listDiffType,
  listDiffDetailSetting,
  data,
  label,
}: {
  listDiffDetailSetting: string[];
  listDiffType: string[];
  data: IAutoSignProfile | null;
  label: string;
}) => {
  const {t} = useTranslation();
  return (
    <ViewCM style={styles.ctnInfo}>
      <TextCM style={styles.txtLabel}>{label}</TextCM>
      {listDiffType.includes('signType') && (
        <ViewCM style={styles.diffInfoCtn}>
          <ViewCM style={styles.item}>
            <TextCM style={styles.txt400small}>
              {t('GS.autoConfig.typeSignature')}
            </TextCM>
            <TextCM>
              {data?.signType.map(item => t(mappingSignType(item))).join(', ')}
            </TextCM>
          </ViewCM>
        </ViewCM>
      )}
      {listDiffType.includes('personalName') && (
        <ViewCM style={styles.diffInfoCtn}>
          <ViewCM style={styles.item}>
            <TextCM style={styles.txt400small}>{t('GS.history.name')}</TextCM>
            <TextCM>{data?.personalName}</TextCM>
          </ViewCM>
        </ViewCM>
      )}
      {listDiffDetailSetting.map((item, index) => {
        let imgSignImg = '';
        let imgHeaderCustom = '';
        let imgLogoCustom = '';

        if (item === IAutoConfigSignType['sign_fca.passcode']) {
          imgHeaderCustom =
            data?.signSetting?.['sign_fca.passcode']?.imageHeaderCustom ?? '';

          imgLogoCustom =
            data?.signSetting?.['sign_fca.passcode']?.imageLogoCustom ?? '';
        }

        if (item === IAutoConfigSignType['Sign-Image']) {
          imgSignImg = data?.signSetting?.['Sign-Image']?.value ?? '';
        }

        if (item === IAutoConfigSignType['Sign-Image'] && imgSignImg === '')
          return null;

        if (
          item === IAutoConfigSignType['sign_fca.passcode'] &&
          imgHeaderCustom === '' &&
          imgLogoCustom === ''
        )
          return null;
        return (
          <ViewCM style={styles.diffInfoCtn} key={index}>
            <ViewCM style={styles.item}>
              <TextCM style={styles.txt400small}>Cấu hình</TextCM>
              <TextCM>{t(mappingSignType(item))}</TextCM>
            </ViewCM>
            {item === IAutoConfigSignType['Sign-Image'] && (
              <ViewCM>
                {imgSignImg && (
                  <ImageView
                    uri={imgSignImg}
                    label={t('GS.history.signatureImage')}
                  />
                )}
                {data?.signSetting?.['Sign-Image']?.default && (
                  <ViewCM style={styles.uuidCtn}>
                    <TextCM style={styles.txt400small}>
                      {t('GS.history.signatureImage')}
                    </TextCM>
                    <TextCM style={styles.uuidText}>
                      {t('GS.addConfigSignature.useSystemImage')}
                    </TextCM>
                  </ViewCM>
                )}
              </ViewCM>
            )}
            {item === IAutoConfigSignType['sign_fca.passcode'] && (
              <ViewCM style={styles.ctnPassCodeImg}>
                <ViewCM style={styles.uuidCtn}>
                  <TextCM style={styles.txt400small}>UUID</TextCM>
                  <TextCM style={styles.uuidText}>
                    {data?.signSetting?.['sign_fca.passcode']?.username ?? ''}
                  </TextCM>
                </ViewCM>
                {imgLogoCustom && (
                  <ImageView
                    uri={imgLogoCustom}
                    label={t('GS.addConfigSignature.logoImage')}
                  />
                )}
                {imgHeaderCustom && (
                  <ImageView
                    uri={imgHeaderCustom}
                    label={t('GS.addConfigSignature.titleImage')}
                  />
                )}
              </ViewCM>
            )}
            {item === IAutoConfigSignType['text_control'] && (
              <ViewCM style={styles.uuidCtn}>
                <TextCM style={styles.txt400small}>
                  {t('GS.history.value')}
                </TextCM>
                <TextCM style={styles.uuidText}>
                  {data?.signSetting?.text_control?.value ?? ''}
                </TextCM>
              </ViewCM>
            )}
          </ViewCM>
        );
      })}
    </ViewCM>
  );
};

const ImageView = ({uri, label}: {uri?: string; label: string}) => {
  return (
    <ViewCM style={styles.viewImage}>
      <TextCM style={styles.nameImg}>{label}</TextCM>
      <ViewCM style={styles.ctnImage}>
        <Image
          resizeMode="contain"
          style={styles.imageDraw}
          source={{
            uri: uri ?? '',
          }}
        />
      </ViewCM>
    </ViewCM>
  );
};

export default ModalDetailHistory;
