import React from 'react';
import {useTranslation} from 'react-i18next';
import {Image, TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {useAppSelector} from '../../../../hook/useRedux';
import TextCM from '../../../../components/Text';
import {IconAvatarDefault, IconHome} from '../../../../assets/images';
import {String} from '../../../../constants';
import {useNavigation} from '@react-navigation/native';

const Header = () => {
  const {t} = useTranslation();
  const navigation = useNavigation();
  const user = useAppSelector(state => state.account.dataAccount);

  return (
    <View style={styles.container}>
      <View>
        {user.avatar ? (
          <Image
            source={{uri: String.PREFIX_IMG_BASE64 + user.avatar}}
            style={styles.avatar}
          />
        ) : (
          <View style={styles.viewNoAvatar}>
            <IconAvatarDefault width={40} height={40} />
          </View>
        )}
      </View>
      <View style={styles.viewName}>
        <TextCM style={styles.txtHello}>{t('HM.TxtHello')},</TextCM>
        <TextCM
          style={styles.txtName}>{`${user.firstName} ${user.lastName}`}</TextCM>
      </View>
      <TouchableOpacity onPress={() => navigation.goBack()}>
        <IconHome width={20} height={20} />
      </TouchableOpacity>
    </View>
  );
};

export default Header;
