import React, {useEffect, useState} from 'react';

import {useNavigation, useRoute} from '@react-navigation/native';
import {isUndefined} from 'lodash';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import {getListActions, IAutoConfigAction, mappingSignType} from './helper';
import styles from './styles';
import ModalHistoryConfigSignature from './components/ModalHistoryConfigSignature';
import {useAppDispatch} from '../../../hook/useRedux';
import {NavigationName} from '../../../constants';
import TextCM from '../../../components/Text';
import {View as ViewCM} from 'react-native';
import Toast from 'react-native-toast-message';
import HeaderCM from '../../../components/Header/HeaderCM';
import {DateUtils} from '../../../utils';
import {
  IcCheckbox,
  IconGreyCheckSelected,
  IconGreyPlus,
  IconWhitePlus,
} from '../../../assets/images';
import SwitchCM from '../../../components/Switch';
import {SizeDP} from '../../../constants/Size';
import ModalConfirm from '../../../components/ModalConfirm';
import {IAutoSignProfile} from '../../../services/interface';
import {useGeneralSettingServices} from '../../../hook/apiHook/useApi';

const AutoConfigSignature = () => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const generalSettingServices = useGeneralSettingServices();

  const route = useRoute<any>();
  const reload = route.params?.reload;

  const [showModal, setShowModal] = useState({
    modalConfirmDelete: false,
    modalHistory: false,
  });

  const [data, setData] = useState<IAutoSignProfile>();

  const onToggleModal = (type: string) => () => {
    switch (type) {
      case 'modalConfirmDelete':
        setShowModal({
          ...showModal,
          modalConfirmDelete: !showModal.modalConfirmDelete,
        });
        break;
      case 'modalHistory':
        setShowModal({
          ...showModal,
          modalHistory: !showModal.modalHistory,
        });
        break;
      default:
        break;
    }
  };

  const onPressActionItem = (item: IAutoConfigAction) => () => {
    switch (item) {
      case IAutoConfigAction.watchHisory:
        onToggleModal('modalHistory')();
        break;
      case IAutoConfigAction.deleteConfig:
        onToggleModal('modalConfirmDelete')();
        break;
      case IAutoConfigAction.editConfig:
        navigation.navigate(NavigationName.AddAutoConfigSignature, {
          isEdit: true,
        });
        break;
      default:
        break;
    }
  };

  const renderItemAction = (value: any) => {
    return (
      <TouchableOpacity
        style={styles.btnAction}
        key={value.type}
        onPress={onPressActionItem(value.type)}>
        <ViewCM style={styles.viewIcon}>{value.icon}</ViewCM>
        <TextCM style={styles.txtNameAction}>{t(value.name)}</TextCM>
      </TouchableOpacity>
    );
  };

  useEffect(() => {
    getData();
  }, [reload]);

  const getData = async () => {
    try {
      const res = await generalSettingServices.getAutoSignProfiles();
      setData(res?.[0]);
    } catch (error: any) {}
  };

  const onToggleStatus = async () => {
    try {
      if (data) {
        const res = await generalSettingServices.updateAutoSignProfile({
          ...data,
          active: !data.active,
        });
        setData(res);
        Toast.show({
          type: 'success',
          text1: t('GS.autoConfig.updateStatusSuccess'),
        });
      }
    } catch (error: any) {
      Toast.show({
        type: 'error',
        text1: t('GS.autoConfig.updateStatusFail'),
      });
    }
  };

  const deleteAutoSignProfile = async () => {
    try {
      if (data) {
        await generalSettingServices.deleteAutoSignProfile(data.id ?? 0);
        Toast.show({
          type: 'success',
          text1: t('GS.autoConfig.deleteSuccess'),
        });
        getData();
      }
    } catch (error: any) {
      Toast.show({
        type: 'error',
        text1: t('GS.autoConfig.deleteFail'),
      });
    } finally {
      onToggleModal('modalConfirmDelete')();
    }
  };

  const onPressAddSignature = () => {
    navigation.navigate(NavigationName.AddAutoConfigSignature as never);
  };

  const isDisabledButton = !isUndefined(data);

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM title={t('GS.autoConfig.text')} />
      {isUndefined(data) ? (
        <ViewCM style={styles.body}>
          <TextCM style={styles.txtNoRecord}>
            {t('GS.autoConfig.emptyConfig')}
          </TextCM>
        </ViewCM>
      ) : (
        <ViewCM style={styles.body}>
          <TextCM style={styles.txtLabel}>
            {t('GS.autoConfig.infoConfig')}
          </TextCM>
          <ViewCM style={styles.infoCtn}>
            <ViewCM style={styles.viewItem}>
              <TextCM style={styles.txtField}>
                {t('GS.autoConfig.nameSigner')}
              </TextCM>
              <TextCM>{data?.personalName}</TextCM>
            </ViewCM>
            <ViewCM style={styles.viewItem}>
              <TextCM style={styles.txtField}>{t('AI.TxtEmail')}</TextCM>
              <TextCM>{data?.email}</TextCM>
            </ViewCM>
            <ViewCM style={styles.viewItem}>
              <TextCM style={styles.txtField}>
                {t('GS.autoConfig.typeSignature')}
              </TextCM>
              <TextCM>
                {data?.signType
                  .map(item => t(mappingSignType(item)))
                  .join(', ')}
              </TextCM>
            </ViewCM>
            <ViewCM style={styles.viewItem}>
              <TextCM style={styles.txtField}>
                {t('GS.autoConfig.createDay')}
              </TextCM>
              <TextCM>
                {DateUtils.convertDateToDDMMYYYYhhmm(data?.createdDate || '')}
              </TextCM>
            </ViewCM>
            <ViewCM style={styles.viewItem}>
              <TextCM style={styles.txtField}>
                {t('GS.autoConfig.haveCondition')}
              </TextCM>
              {data?.conditional ? <IconGreyCheckSelected /> : <IcCheckbox />}
            </ViewCM>
            <ViewCM style={styles.viewItem}>
              <TextCM style={styles.txtField}>
                {t('GS.autoConfig.status')}
              </TextCM>
              <SwitchCM isEnabled={data?.active} onPress={onToggleStatus} />
            </ViewCM>
          </ViewCM>
          <ViewCM style={styles.action}>
            {getListActions().map(renderItemAction)}
          </ViewCM>
        </ViewCM>
      )}
      <ViewCM style={styles.buttonCtn}>
        <TouchableOpacity
          disabled={isDisabledButton}
          onPress={onPressAddSignature}
          style={[
            styles.buttonStyle,
            isDisabledButton && {backgroundColor: '#D0D5DD'},
          ]}>
          {isDisabledButton ? (
            <IconGreyPlus width={SizeDP(24)} height={SizeDP(24)} />
          ) : (
            <IconWhitePlus width={SizeDP(24)} height={SizeDP(24)} />
          )}
          <TextCM
            style={[styles.txtButton, isDisabledButton && {color: '#667085'}]}>
            {t('GS.autoConfig.addConfig')}
          </TextCM>
        </TouchableOpacity>
      </ViewCM>
      <ModalConfirm
        isVisible={showModal.modalConfirmDelete}
        title={t('GS.autoConfig.deleteAutoConfig')}
        content={t('GS.autoConfig.confirmDeleteAutoConfig')}
        onClose={onToggleModal('modalConfirmDelete')}
        onConfirm={deleteAutoSignProfile}
      />
      {showModal.modalHistory && (
        <ModalHistoryConfigSignature
          onClose={onToggleModal('modalHistory')}
          isVisible={showModal.modalHistory}
          id={data?.id ?? 0}
        />
      )}
    </SafeAreaView>
  );
};

export default AutoConfigSignature;
