import React, {useEffect, useMemo, useRef, useState} from 'react';

import {yupResolver} from '@hookform/resolvers/yup';

import {
  Controller,
  FormProvider,
  useForm,
  useFormContext,
} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {Image, TouchableOpacity} from 'react-native';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import {SafeAreaView} from 'react-native-safe-area-context';
import SignatureScreen, {SignatureViewRef} from 'react-native-signature-canvas';
import {IAutoConfigSignType} from '../auto-config-signature/helper';
import ChooseImage from './components/ChooseImage';
import ModalTypeSignature from './components/ModalTypeSignature';
import {LIST_IMAGE_SOURCE, LIST_SIGN_TYPE, STYLE_PAD} from './helper';
import styles from './styles';
import * as yup from 'yup';
import {useNavigation, useRoute} from '@react-navigation/native';
import {useAppDispatch} from '../../../hook/useRedux';
import {Color, NavigationName, String} from '../../../constants';
import {
  EyesIcon,
  EyesIconOpen,
  IcCheckbox,
  IcCheckboxSelect,
  IconBlueQuestions,
} from '../../../assets/images';
import {SizeDP} from '../../../constants/Size';
import TextCM from '../../../components/Text';
import {View as ViewCM} from 'react-native';
import GroupRadio, {GroupData} from '../../../components/GroupRadio';
import ButtonCM from '../../../components/Button';
import Toast from 'react-native-toast-message';
import HeaderCM from '../../../components/Header/HeaderCM';
import Picker from '../../document/document-share/tabScreens/shareScreen/components/Picker';
import TextFieldCM from '../../../components/TextField';
import {IAutoSignProfile} from '../../../services/interface';
import {useGeneralSettingServices} from '../../../hook/apiHook/useApi';
const AddAutoConfigSignature = () => {
  const {t} = useTranslation();
  const SCHEMA = yup.object().shape({
    //image signature
    currentTypeSelected: yup.array(),
    nameOfSigner: yup.string().required(t('SU.fieldRequired')),
    // passcode
    uuid: yup.string().required(t('SU.fieldRequired')),
    passwordPassCode: yup.string().required(t('SU.fieldRequired')),
    // text value
    textValue: yup.string().required(t('SU.fieldRequired')),
  });
  const navigation = useNavigation<any>();

  const generalSettingServices = useGeneralSettingServices();

  const route = useRoute<any>();
  const isEdit = route.params?.isEdit;

  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(SCHEMA),
    defaultValues: {
      nameOfSigner: '',
      currentTypeSelected: [],
    },
  });

  const [data, setData] = useState<IAutoSignProfile>();

  const [loading, setLoading] = useState(false);

  const [showModal, setShowModal] = useState({
    modalTypeSignature: false,
  });

  const [sourceImage, setSourceImage] = useState<any>();

  const [isCondition, setIsCondition] = useState(false);

  // config image signature

  const ref = useRef<SignatureViewRef>(null);

  const [scrollEnabled, setScrollEnabled] = useState(true);

  const [imageDrawing, setImageDrawing] = useState<string>('');

  const [image, setImage] = useState<any>();

  // config passcode
  const [isConfigLogoPasscode, setIsConfigLogoPasscode] = useState(false);
  const [logoImage, setLogoImage] = useState<any>('');
  const [titleImage, setTitleImage] = useState<any>('');

  const toggleModal = (type: string) => () => {
    switch (type) {
      case 'modalTypeSignature':
        setShowModal({
          ...showModal,
          modalTypeSignature: !showModal.modalTypeSignature,
        });
        break;

      default:
        break;
    }
  };

  useEffect(() => {
    if (isEdit) {
      getData();
    }
  }, [isEdit]);

  const getData = async () => {
    try {
      const res = await generalSettingServices.getAutoSignProfiles();
      const dataRes = res?.[0];
      setData(dataRes);
      methods.setValue('nameOfSigner', dataRes?.personalName);
      methods.setValue(
        'currentTypeSelected',
        dataRes?.signType.map((item: string) => {
          return LIST_SIGN_TYPE.find(itemType => itemType.id === item);
        }),
      );
      setIsCondition(dataRes?.conditional);
      if (dataRes?.signSetting) {
        if (dataRes?.signSetting['Sign-Image']) {
          const signImage = dataRes?.signSetting['Sign-Image'];
          const sourceImageFromres = signImage.drawImage
            ? 'draw'
            : signImage.default
            ? 'system'
            : 'gallery';
          setSourceImage(
            LIST_IMAGE_SOURCE.find(item => item.id === sourceImageFromres),
          );
          if (sourceImageFromres === 'gallery') {
            setImage({
              data: signImage.value?.replace(String.PREFIX_IMG_BASE64, ''),
            });
          }
          if (sourceImageFromres === 'draw') {
            setImageDrawing(signImage.value ?? '');
          }
        }
        if (dataRes?.signSetting['sign_fca.passcode']) {
          const signFcaPasscode = dataRes?.signSetting['sign_fca.passcode'];
          setIsConfigLogoPasscode(signFcaPasscode.custormSignatureImage);
          setLogoImage({
            data: signFcaPasscode.imageLogoCustom?.replace(
              String.PREFIX_IMG_BASE64,
              '',
            ),
          });
          setTitleImage({
            data: signFcaPasscode.imageHeaderCustom?.replace(
              String.PREFIX_IMG_BASE64,
              '',
            ),
          });
          methods.setValue('uuid', signFcaPasscode.username);
        }
        if (dataRes?.signSetting['text_control']) {
          methods.setValue(
            'textValue',
            dataRes?.signSetting['text_control'].value,
          );
        }
      }
    } catch (error: any) {}
  };

  const onChooseTypeSignature = (array: any) => {
    methods.setValue('currentTypeSelected', array);
  };

  const renderConditional = () => {
    const onPressConditional = () => {
      setIsCondition(!isCondition);
    };
    return (
      <TouchableOpacity style={[styles.viewItem]} onPress={onPressConditional}>
        {isCondition ? (
          <IcCheckboxSelect width={SizeDP(24)} height={SizeDP(24)} />
        ) : (
          <IcCheckbox width={SizeDP(24)} height={SizeDP(24)} />
        )}
        <TextCM style={[styles.txtConditional]}>
          {t('GS.addConfigSignature.haveCondition')}
        </TextCM>
        <IconBlueQuestions
          style={styles.questionIcon}
          width={SizeDP(16)}
          height={SizeDP(16)}
        />
      </TouchableOpacity>
    );
  };

  const handleBegin = () => {
    setScrollEnabled(false);
  };

  const handleEnd = () => {
    setScrollEnabled(true);
  };

  const handleSignature = (signature: any) => {
    setImageDrawing(signature);
  };

  const onPressDeleteDrawSignature = () => {
    ref.current?.clearSignature();
    setImageDrawing('');
  };

  const onPressSaveDrawSignature = () => {
    ref.current?.readSignature();
  };

  const renderConfigImageSignature = () => {
    const isRender = methods
      .getValues('currentTypeSelected')
      ?.find((item: any) => item.id === IAutoConfigSignType['Sign-Image']);
    if (!isRender) return null;

    const onPress = (item: GroupData) => {
      setSourceImage(item);
      if (item.id !== 'draw') {
        setImageDrawing('');
      }
    };
    return (
      <ViewCM>
        <ViewCM style={styles.seperateView} />
        <ViewCM style={styles.configImageCtn}>
          <TextCM style={styles.txt16}>
            {t('GS.addConfigSignature.configSignImage')}
          </TextCM>
          <ViewCM style={styles.quoteCtn}>
            <TextCM style={styles.txtQuote}>
              {t('GS.addConfigSignature.quoteConfigImage')}
            </TextCM>
          </ViewCM>
          <ViewCM style={styles.signatureCtn}>
            <TextCM style={styles.txt14}>Ảnh chữ ký</TextCM>
            <TextCM style={styles.requiredIndicator}>*</TextCM>
          </ViewCM>
          <ViewCM style={styles.radioCtn}>
            <GroupRadio
              data={LIST_IMAGE_SOURCE}
              onPressData={onPress}
              currentValue={sourceImage}
            />
          </ViewCM>
          {sourceImage?.id === 'draw' ? (
            <ViewCM>
              {imageDrawing ? (
                <ViewCM style={styles.viewDrawSignature}>
                  <Image
                    resizeMode="contain"
                    style={styles.imageDraw}
                    source={{
                      uri: imageDrawing,
                    }}
                  />
                </ViewCM>
              ) : (
                <SignatureScreen
                  style={styles.stylesSignatureScreen}
                  ref={ref}
                  onBegin={handleBegin}
                  onEnd={handleEnd}
                  onOK={handleSignature}
                  autoClear={false}
                  webStyle={STYLE_PAD}
                  trimWhitespace={true}
                  imageType="image/png"
                  penColor={'#000000'}
                />
              )}
              {imageDrawing ? (
                <ViewCM style={styles.groupButton}>
                  <ButtonCM
                    type="white"
                    onPress={onPressDeleteDrawSignature}
                    label={t('GS.addConfigSignature.reDraw')}
                    style={{height: SizeDP(32)}}
                  />
                </ViewCM>
              ) : (
                <ViewCM style={styles.groupButton}>
                  <ButtonCM
                    type="white"
                    onPress={onPressDeleteDrawSignature}
                    label={t('CM.BtnClear')}
                    style={{height: SizeDP(32)}}
                  />
                  <ButtonCM
                    onPress={onPressSaveDrawSignature}
                    label={t('CM.TxtSave')}
                    style={{height: SizeDP(32)}}
                  />
                </ViewCM>
              )}
            </ViewCM>
          ) : (
            <ViewCM></ViewCM>
          )}
          {sourceImage?.id === 'gallery' && (
            <ChooseImage
              data={image}
              onChooseImage={setImage}
              label={t('AC.TxtSignatureImage')}
            />
          )}
        </ViewCM>
      </ViewCM>
    );
  };

  const renderConfigPasscode = () => {
    const isRender = methods
      .getValues('currentTypeSelected')
      ?.find(
        (item: any) => item.id === IAutoConfigSignType['sign_fca.passcode'],
      );
    if (!isRender) return null;

    const onPressConfigLogoPasscode = () => {
      setIsConfigLogoPasscode(!isConfigLogoPasscode);
    };

    return (
      <ViewCM>
        <ViewCM style={styles.seperateView} />
        <ViewCM style={styles.configImageCtn}>
          <TextCM style={styles.txt16}>
            {t('GS.addConfigSignature.cloudPassCodeTitle')}
          </TextCM>
          <ViewCM style={styles.quoteCtn}>
            <TextCM style={styles.txtQuote}>
              {t('GS.addConfigSignature.quoteCloudPassCode')}
            </TextCM>
          </ViewCM>
          <YupTextField
            isRequired={true}
            controlName="uuid"
            label={t('GS.addConfigSignature.uuid')}
          />
          <PasswordField
            controlName={'passwordPassCode'}
            label={t('GS.password')}
            isRequired={true}
          />
          <TouchableOpacity
            style={[styles.viewItem]}
            onPress={onPressConfigLogoPasscode}>
            {isConfigLogoPasscode ? (
              <IcCheckboxSelect width={SizeDP(24)} height={SizeDP(24)} />
            ) : (
              <IcCheckbox width={SizeDP(24)} height={SizeDP(24)} />
            )}
            <TextCM style={[styles.txtConditional]}>
              {t('GS.addConfigSignature.adjustLogoSignature')}
            </TextCM>
          </TouchableOpacity>
          {isConfigLogoPasscode && (
            <ChooseImage
              data={logoImage}
              onChooseImage={setLogoImage}
              label={t('GS.addConfigSignature.logoImage')}
            />
          )}
          {isConfigLogoPasscode && (
            <ChooseImage
              data={titleImage}
              onChooseImage={setTitleImage}
              label={t('GS.addConfigSignature.titleImage')}
            />
          )}
        </ViewCM>
      </ViewCM>
    );
  };

  const renderConfigTextSignature = () => {
    const isRender = methods
      .getValues('currentTypeSelected')
      ?.find((item: any) => item.id === IAutoConfigSignType['text_control']);
    if (!isRender) return null;
    return (
      <ViewCM>
        <ViewCM style={styles.seperateView} />
        <ViewCM style={styles.configImageCtn}>
          <TextCM style={styles.txt16}>
            {t('GS.addConfigSignature.configText')}
          </TextCM>
          <ViewCM style={styles.quoteCtn}>
            <TextCM style={styles.txtQuote}>
              {t('GS.addConfigSignature.quoteConfigText')}
            </TextCM>
          </ViewCM>
          <YupTextField
            isRequired={true}
            controlName="textValue"
            label={t('GS.addConfigSignature.typingText')}
          />
        </ViewCM>
      </ViewCM>
    );
  };

  const onSubmit = async () => {
    try {
      setLoading(true);
      let sign_FcaPasscode = undefined;
      if (
        methods
          .getValues('currentTypeSelected')
          ?.find(item => item.id === IAutoConfigSignType['sign_fca.passcode'])
      ) {
        const res = await generalSettingServices.encodePassword(
          methods.getValues('passwordPassCode'),
        );
        sign_FcaPasscode = {
          custormSignatureImage: isConfigLogoPasscode,
          imageHeaderCustom: isConfigLogoPasscode
            ? String.PREFIX_IMG_BASE64 + titleImage?.data
            : null,
          imageLogoCustom: isConfigLogoPasscode
            ? String.PREFIX_IMG_BASE64 + logoImage?.data
            : null,
          password: res,
          username: methods.getValues('uuid'),
        };
      }
      const signSettings = {
        'Sign-Image': methods
          .getValues('currentTypeSelected')
          ?.find(item => item.id === IAutoConfigSignType['Sign-Image'])
          ? {
              value:
                sourceImage.id === 'system'
                  ? null
                  : sourceImage.id === 'draw'
                  ? imageDrawing
                  : String.PREFIX_IMG_BASE64 + image?.data,
              default: sourceImage.id === 'system',
              drawImage: sourceImage.id === 'draw',
            }
          : undefined,
        'sign_fca.passcode': sign_FcaPasscode,
        text_control: methods
          .getValues('currentTypeSelected')
          ?.find(item => item.id === IAutoConfigSignType['text_control'])
          ? {
              value: methods.getValues('textValue'),
            }
          : undefined,
      };
      if (isEdit) {
        await generalSettingServices.updateAutoSignProfile({
          id: data?.id ?? 0,
          personalName: methods.getValues('nameOfSigner'),
          email: null,
          signType: (methods.getValues('currentTypeSelected') ?? []).map(
            (item: any) => item.id,
          ),
          signSetting: signSettings,
          active: false,
          owner: null,
          createdDate: data?.createdDate ?? null,
          lastModifiedDate: null,
          createdBy: null,
          lastModifiedBy: null,
          conditional: isCondition,
        });
        Toast.show({
          type: 'success',
          text1: t('GS.addConfigSignature.updateSuccess'),
        });
      } else {
        const data = await generalSettingServices.createAutoSignProfile({
          id: null,
          personalName: methods.getValues('nameOfSigner'),
          email: null,
          signType: (methods.getValues('currentTypeSelected') ?? []).map(
            (item: any) => item.id,
          ),
          signSetting: signSettings,
          active: false,
          owner: null,
          createdDate: null,
          lastModifiedDate: null,
          createdBy: null,
          lastModifiedBy: null,
          conditional: isCondition,
        });
        Toast.show({
          type: 'success',
          text1: t('GS.addConfigSignature.addSuccess'),
        });
      }
      navigation.navigate(NavigationName.AutoConfigSignature, {
        reload: Date.now(),
      });
    } catch (error: any) {
      if (error?.data?.detail === 'username is not exsist ') {
        Toast.show({
          type: 'error',
          text1: t('GS.addConfigSignature.errorUuid'),
        });
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.errorExist'),
        });
      }
    } finally {
      setLoading(false);
    }
  };

  const isDisableButton = useMemo(() => {
    if (
      (methods.getValues('currentTypeSelected') ?? []).length === 0 ||
      methods.getValues('nameOfSigner') === ''
    )
      return true;
    if (
      methods
        .getValues('currentTypeSelected')
        ?.find(item => item.id === IAutoConfigSignType['Sign-Image'])
    ) {
      if (!sourceImage) return true;
      if (sourceImage?.id === 'draw' && !imageDrawing) return true;
      if (sourceImage?.id === 'gallery' && !image) return true;
    }

    if (
      methods
        .getValues('currentTypeSelected')
        ?.find(item => item.id === IAutoConfigSignType['sign_fca.passcode'])
    ) {
      if (!methods.getValues('uuid') || !methods.getValues('passwordPassCode'))
        return true;
      if (isConfigLogoPasscode && (!logoImage || !titleImage)) return true;
    }

    if (
      methods
        .getValues('currentTypeSelected')
        ?.find(item => item.id === IAutoConfigSignType['text_control'])
    ) {
      if (!methods.getValues('textValue')) return true;
    }

    return false;
  }, [
    methods.watch('currentTypeSelected'),
    methods.watch('passwordPassCode'),
    methods.watch('textValue'),
    methods.watch('uuid'),
    sourceImage,
    imageDrawing,
    image,
    isConfigLogoPasscode,
    logoImage,
    titleImage,
  ]);

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM
        title={
          !isEdit
            ? t('GS.addConfigSignature.title')
            : t('GS.addConfigSignature.editTitle')
        }
      />
      <FormProvider {...methods}>
        <KeyboardAwareScrollView
          scrollEnabled={scrollEnabled}
          style={styles.body}>
          <ViewCM style={styles.infoCtn}>
            <YupTextField
              isRequired={true}
              controlName="nameOfSigner"
              label={t('GS.addConfigSignature.nameSigner')}
            />
            <Picker
              label={t('GS.addConfigSignature.typeSignature')}
              isRequired={true}
              onPress={toggleModal('modalTypeSignature')}
              value={
                (methods.getValues('currentTypeSelected') || [])
                  .map((item: any) => item.label)
                  .join(', ') || ''
              }
            />
            {renderConditional()}
          </ViewCM>
          {renderConfigImageSignature()}
          {renderConfigPasscode()}
          {renderConfigTextSignature()}
        </KeyboardAwareScrollView>
        <ViewCM style={styles.btnContainer}>
          <ButtonCM
            disabled={isDisableButton}
            label={t('CM.BtnConfirm')}
            onPress={onSubmit}
            loading={loading}
          />
        </ViewCM>
        {showModal.modalTypeSignature && (
          <ModalTypeSignature
            onClose={toggleModal('modalTypeSignature')}
            isVisible={showModal.modalTypeSignature}
            data={LIST_SIGN_TYPE}
            onSubmit={onChooseTypeSignature}
            currentSelected={methods.getValues('currentTypeSelected') || []}
          />
        )}
      </FormProvider>
    </SafeAreaView>
  );
};

type TextFieldProps = {
  controlName: string;
  label: string;
  maxLength?: number;
  onPressIconRight?: () => void;
  viewIconRight?: React.ReactNode;
  isDisabled?: boolean;
  editable?: boolean;
  isRequired?: boolean;
  paramRef?: React.Ref<any>;
};

const YupTextField = ({
  controlName,
  label,
  maxLength,
  onPressIconRight,
  viewIconRight,
  isRequired,
  editable,
  paramRef,
}: TextFieldProps) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  return (
    <ViewCM>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          return (
            <TextFieldCM
              ref={paramRef}
              label={label}
              placeholder={label}
              value={value}
              onBlur={onBlur}
              onChangeText={onChange}
              onIconPress={onPressIconRight}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={viewIconRight}
              inputContainerStyle={{backgroundColor: Color.White}}
              editable={editable}
              isRequired={isRequired}
              // styleIconRight={{width: 'auto'}}
            />
          );
        }}
      />
    </ViewCM>
  );
};

type PasswordFieldProps = {
  controlName: string;
  label: string;
  isRequired?: boolean;
  maxLength?: number;
};

const PasswordField = ({
  controlName,
  label,
  isRequired,
  maxLength,
}: PasswordFieldProps) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  const [isSecureText, setIsSecureText] = useState<boolean>(true);

  return (
    <ViewCM>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          const onChangeText = (text: string) => {
            onChange(text.replace(/\s/g, ''));
          };
          return (
            <TextFieldCM
              label={label}
              placeholder={label}
              isRequired={isRequired}
              value={value}
              onBlur={onBlur}
              onChangeText={onChangeText}
              secureTextEntry={isSecureText}
              onIconPress={() => setIsSecureText(!isSecureText)}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={
                isSecureText ? (
                  <EyesIcon width={SizeDP(24)} height={SizeDP(24)} />
                ) : (
                  <EyesIconOpen width={SizeDP(24)} height={SizeDP(24)} />
                )
              }
            />
          );
        }}
      />
    </ViewCM>
  );
};

export default AddAutoConfigSignature;
