import {useRoute} from '@react-navigation/native';
import {useTranslation} from 'react-i18next';
import Pdf from 'react-native-pdf';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useAppSelector} from '../../../../../hook/useRedux';
import HeaderCM from '../../../../../components/Header/HeaderCM';
import {BASE_URL} from '../../../../../services/httpClient';

const ViewPdfDocument = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const envelopeId = route?.params?.envelopeId;
  const docId = route?.params?.docId;
  const {access_token} = useAppSelector(
    state => state.account.infoResponseLogin,
  );
  const getCurrentPdfFileTemplate = () => {
    return `${BASE_URL}/services/envelope/api/envelope/${envelopeId}/doc/${docId}/content`;
  };
  return (
    <SafeAreaView style={{flex: 1}} edges={['bottom']}>
      <HeaderCM title={t('CM.TxtTabDocuments')} />
      <Pdf
        trustAllCerts={false}
        style={{flex: 1}}
        source={{
          headers: {
            Authorization: `Bearer ${access_token}`,
          },
          uri: getCurrentPdfFileTemplate(),
        }}
        onError={e => console.log(e)}
      />
    </SafeAreaView>
  );
};

export default ViewPdfDocument;
