import {isEmpty} from 'lodash';
import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {getPayloadSignDozen} from '../ModalInfoCA/helper';
import ListTabType from './components/ListTabType';
import SignatureDigital from './components/SignatureDigital';
import SignatureFromAccount from './components/SignatureFromAccount';
import SignatureFromImage from './components/SignatureFromImage';
import styles from './styles';
import {useCreateNotiServices} from '../../../../../hook/apiHook/useApi';
import {View} from 'react-native';
import BottomSheetCM from '../../../../../components/BottomSheet';
import Toast from 'react-native-toast-message';
import useStoreNoti from '../../../store/store';

type Props = {
  isVisible: boolean;
  onClose: () => void;
  onNextStep: () => void;
};

export enum TabType {
  Account = 'Account',
  File = 'File',
  Art = 'Art',
}

const ModalSignDozen = ({isVisible, onClose, onNextStep}: Props) => {
  const {t} = useTranslation();
  const NotificationServices = useCreateNotiServices();
  const [tabType, setTabType] = useState(TabType.Account);

  const {
    currentSignDozens,
    reLoadDataNotification,
    setImageSignature,
    setCurrentSignDozens,
    setReloadDataNotification,
  } = useStoreNoti();

  const is2Tep = () => {
    const lsCAPass = currentSignDozens.filter(i => i.inputSignType === '2');
    const lsSign2 = currentSignDozens.filter(i => i.inputSignType === '3');
    return !isEmpty(lsCAPass) || !isEmpty(lsSign2);
  };

  const onSave = async (value: string) => {
    const lsSignImage = currentSignDozens.filter(i => i.inputSignType === '1');

    const lsCAPass = currentSignDozens.filter(i => i.inputSignType === '2');

    const lsSign2 = currentSignDozens.filter(i => i.inputSignType === '3');

    const lsNo = currentSignDozens.filter(i => i.inputSignType === '0');

    const bodyNo = lsNo.map(item =>
      getPayloadSignDozen(item, null, null, null),
    );

    const newValue = await NotificationServices.convertImage300250(value);

    const bodySignImage = lsSignImage.map(item =>
      getPayloadSignDozen(item, null, null, newValue),
    );

    if (isEmpty(lsCAPass) && isEmpty(lsSign2)) {
      try {
        await NotificationServices.putProcessing(
          currentSignDozens.map(item => item.id),
        );
        await NotificationServices.signDozen([...bodySignImage, ...bodyNo]);
        setCurrentSignDozens([]);
        setReloadDataNotification(!reLoadDataNotification);
        Toast.show({
          type: 'success',
          text1: t('NT.message.successSignDozen'),
        });
      } catch (error) {
        Toast.show({
          type: 'error',
          text1: t('CM.TxtSystemError'),
        });
      } finally {
        onClose();
      }
    } else {
      setImageSignature(newValue);
      onNextStep();
    }
  };

  const Content = () => {
    return (
      <View style={styles.ctn}>
        <ListTabType tabType={tabType} setTabType={setTabType} />
        {tabType === TabType.Account && (
          <SignatureFromAccount onSave={onSave} />
        )}
        {tabType === TabType.File && <SignatureFromImage onSave={onSave} />}
        {tabType === TabType.Art && <SignatureDigital onSave={onSave} />}
      </View>
    );
  };

  return (
    <View>
      <BottomSheetCM
        styleBody={styles.container}
        onClose={onClose}
        isVisible={isVisible}
        title={is2Tep() ? `1. ${t('AC.titleSign')}` : t('AC.titleSign')}
        renderContent={<Content />}
      />
    </View>
  );
};

export default ModalSignDozen;
