import {IRelateDocument} from '../../../../../model/interface/envelope.interface';

export interface IExtendedRelateDocument extends IRelateDocument {
  children: IExtendedRelateDocument[];
  showChildren: Boolean;
}

// Helper function to find or create a node
function findOrCreateNode(
  id: string,
  name: string,
  level: number,
  contextPath: string,
  status: string,
  children: IExtendedRelateDocument[],
  showChildren: boolean,
) {
  let node = children.find(child => child.id === id);
  if (!node) {
    node = {
      id,
      name,
      level,
      contextPath,
      status,
      showChildren: showChildren,
      children: [],
    };
    children.push(node);
  }
  return node;
}

// Function to convert flat data to nested hierarchy
export function convertToHierarchy(
  data: IRelateDocument[],
  showChildren: boolean,
): IExtendedRelateDocument[] {
  const root = {children: []};

  data.forEach(item => {
    const parts = item.contextPath.split('/').filter(Boolean);
    let currentLevel: any = root.children;

    parts.forEach((part, index) => {
      const isLeaf = index === parts.length - 1;
      const id = parts[index];
      const name = isLeaf ? item.name : '';
      const level = isLeaf ? item.level : 0;
      const contextPath = isLeaf ? item.contextPath : '';
      const status = isLeaf ? item.status : '';

      const node = findOrCreateNode(
        id,
        name,
        level,
        contextPath,
        status,
        currentLevel,
        showChildren,
      );
      currentLevel = node.children;
    });
  });

  return root.children;
}

export const toggleNode = (
  nodes: IExtendedRelateDocument[],
  id: string,
): IExtendedRelateDocument[] => {
  return nodes.map(node => {
    if (node.id === id) {
      return {...node, showChildren: !node.showChildren};
    }
    if (node.children) {
      return {...node, children: toggleNode(node.children, id)};
    }
    return node;
  });
};

export const handleContextPath = (contextPath: string) => {
  const arr = contextPath.split('/');
  return `${arr[arr.length - 1]}/${arr[arr.length - 2]}`;
};
