import {yupResolver} from '@hookform/resolvers/yup';
import {isEmpty, some} from 'lodash';
import React, {useEffect, useState} from 'react';
import {
  Controller,
  FormProvider,
  useForm,
  useFormContext,
} from 'react-hook-form';
import {useTranslation} from 'react-i18next';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import * as yup from 'yup';
import PicDateView from '../../../document-list/components/ModalFilter/components/PicDateView';
import ModalTypePermission from './components/ModalTypePermission';
import ModalTypeShare from './components/ModalTypeShare';
import Picker from './components/Picker';
import ShareItem from './components/shareItem';
import {LIST_PERMISSION, TYPE_OF_SHARE} from './helper';
import styles from './styles';
import {
  IDocument,
  IExternalShared,
  IExternalSharedRequest,
} from '../../../../../model/interface/envelope.interface';
import {DateUtils, RegexUtils} from '../../../../../utils';
import TextCM from '../../../../../components/Text';
import {IconBlueClose} from '../../../../../assets/images';
import TextField from '../../../../../components/TextField';
import ButtonCM from '../../../../../components/Button';
import {Color} from '../../../../../constants';
import Toast from 'react-native-toast-message';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

const ShareScreen = ({data}: {data: IDocument}) => {
  const {t} = useTranslation();

  const schema = yup.object().shape({
    currentShareSelected: yup.array(),
    typeShare: yup.string(),
    email: yup.string().matches(RegexUtils.FORMAT_EMAIL, t('SU.wrongEmail')),
    phoneNumber: yup
      .string()
      .matches(RegexUtils.REGEX_PHONE_NUMBER, t('SU.wrongPhoneNumber'))
      .required(t('SU.fieldRequired')),
    // list permission
    permission: yup.object().shape({
      label: yup.string(),
      type: yup.string(),
    }),
  });
  const methods = useForm({
    mode: 'onChange',
    resolver: yupResolver(schema),
    defaultValues: {
      currentShareSelected: [TYPE_OF_SHARE[0]],
      typeShare: TYPE_OF_SHARE[0].label,
      permission: LIST_PERMISSION[0],
    },
  });

  // Edit mode

  const [isEditMode, setIsEditMode] = useState(false);

  const [editSelected, setEditSelected] = useState<IExternalShared | null>(
    null,
  );

  const [fromDateEdit, setFromDateEdit] = useState(new Date());
  const [toDateEdit, setToDateEdit] = useState(
    DateUtils.addMonths(new Date(), 1),
  );

  // End Edit mode

  const [listEmail, setListEmail] = useState<string[]>([]);

  const [fromDate, setFromDate] = useState(new Date());
  const [toDate, setToDate] = useState(DateUtils.addMonths(new Date(), 1));

  const [listExtenalShared, setListExtenalShared] = useState<IExternalShared[]>(
    [],
  );

  const [showModal, setShowModal] = useState({
    modalTypeShare: false,
    modalTypePermission: false,
  });

  const ref = React.useRef<any>(null);

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    getListExternal();
  }, []);

  const getListExternal = async () => {
    try {
      const res = await DocumentServices.getListExternalShared(data.id);
      setListExtenalShared(res);
    } catch (error) {}
  };

  const onSubmit = async () => {
    try {
      const listArray: IExternalSharedRequest[] = listEmail.map(item => {
        return {
          id: null,
          resourceId: data.id,
          resourceName: data.name,
          resourceType: 'e',
          sharedType: 'p',
          personal: item,
          group: null,
          password: null,
          perm: 'v_d',
          fromDate: fromDate.toISOString(),
          toDate: toDate.toISOString(),
        } as IExternalSharedRequest;
      });
      await DocumentServices.postExternalShared(listArray);
      Toast.show({
        type: 'success',
        text1: t('DC.ShareDocument.shareSuccessfully'),
      });
      setListEmail([]);
      await getListExternal();
    } catch (error) {}
  };

  const onSubmitEdit = async () => {
    try {
      const body = {
        ...editSelected,
        fromDate: fromDateEdit.toISOString(),
        toDate: toDateEdit.toISOString(),
      };
      await DocumentServices.editExternalShared(body);
      Toast.show({
        type: 'success',
        text1: t('DC.ShareDocument.shareSuccessfully'),
      });
      setListEmail([]);
      setIsEditMode(false);
      await getListExternal();
    } catch (error) {}
  };

  const deleteExternal = async (item: IExternalShared) => {
    try {
      await DocumentServices.deleteExternalShared(item.id);
      Toast.show({
        type: 'success',
        text1: t('DC.ShareDocument.cancelShare', {name: data.name}),
      });
      await getListExternal();
    } catch (error) {}
  };

  const toggleModal = (modalName: string) => () => {
    switch (modalName) {
      case 'modalTypeShare':
        setShowModal({...showModal, modalTypeShare: !showModal.modalTypeShare});
        break;
      case 'modalTypePermission':
        setShowModal({
          ...showModal,
          modalTypePermission: !showModal.modalTypePermission,
        });
        break;
      default:
        break;
    }
  };

  const onChooseTypeShare = (array: any) => {
    ref.current?.blur();
    methods.setValue('currentShareSelected', array);
    methods.setValue(
      'typeShare',
      array.map((item: any) => item.label).join(', ') || '',
    );
  };

  const onRemoveEmail = (email: string) => () => {
    setListEmail(prev => prev.filter(item => item !== email));
  };

  const renderTag = () => {
    if (isEmpty(listEmail)) {
      return null;
    }
    return (
      <View style={styles.ctnHashtag}>
        {listEmail.map((item, index) => {
          return (
            <View style={styles.viewItemHashtag} key={index}>
              <TextCM style={styles.txtHashtag}>{item}</TextCM>
              <TouchableOpacity onPress={onRemoveEmail(item)}>
                <IconBlueClose width={12} height={12} />
              </TouchableOpacity>
            </View>
          );
        })}
      </View>
    );
  };

  const onPressAddEmail = async () => {
    try {
      const valid = await methods.trigger('email');
      const valueEmail = await methods.getValues('email');
      if (valid && !isEmpty(valueEmail)) {
        setListEmail(prev => [...prev, valueEmail ?? '']);
        methods.setValue('email', '', {shouldValidate: false});
        ref.current?.clear();
      }
    } catch (error) {
    } finally {
    }
  };

  const showHide = React.useMemo(() => {
    return {
      showEmailField: some(methods.getValues('currentShareSelected'), item => {
        return item.id === 'email';
      }),
      showPhoneField: some(methods.getValues('currentShareSelected'), item => {
        return item.id === 'phone';
      }),
    };
  }, [methods.watch('currentShareSelected')]);

  const onChoosePermission = (item: any) => {
    methods.setValue('permission', item);
    toggleModal('modalTypePermission')();
  };

  const onChangeFromDate = (date: any) => {
    setFromDate(date);
  };

  const onChangeToDate = (date: any) => {
    setToDate(date);
  };

  // list external shared

  const onPressEdit = (data: IExternalShared) => {
    setEditSelected(data);
    setIsEditMode(true);
    setFromDateEdit(new Date(data.fromDate));
    setToDateEdit(new Date(data.toDate));
  };

  const renderListShare = () => {
    if (isEmpty(listExtenalShared)) return null;
    return (
      <View style={styles.ctnShareView}>
        <TextCM style={styles.txtLabel16}>
          {t('DC.ShareDocument.listShared')}
        </TextCM>
        <View style={styles.ctnSharedList}>
          {listExtenalShared.map((item, index) => {
            return (
              <ShareItem
                key={index}
                data={item}
                onPressDelete={deleteExternal}
                onPressEdit={onPressEdit}
              />
            );
          })}
        </View>
      </View>
    );
  };

  const renderIsEditMode = () => {
    return (
      <View style={styles.groupTextField}>
        <Picker
          value={TYPE_OF_SHARE[0].label}
          label={t('DC.ShareDocument.chooseTypeShare')}
          onPress={() => {}}
          isRequired={true}
          type="inactive"
          disabled={true}
        />
        <TextField
          isRequired={true}
          label={t('DC.ShareDocument.typeEmail')}
          value={editSelected?.personal}
          isDisabled={true}
        />
        <Picker
          value={LIST_PERMISSION[0].label}
          label={t('DC.ShareDocument.allowPermission')}
          onPress={toggleModal('modalTypePermission')}
          type="inactive"
          disabled={true}
        />
        <View style={styles.viewPicDate}>
          <PicDateView
            label={t('DC.ShareDocument.effectFrom')}
            date={fromDateEdit}
            maxDate={toDateEdit}
            onChangeDate={setFromDateEdit}
          />
          <PicDateView
            label={t('DC.ShareDocument.effectTo')}
            date={toDateEdit}
            minDate={fromDateEdit}
            onChangeDate={setToDateEdit}
          />
        </View>
      </View>
    );
  };

  return (
    <View style={styles.ctnMain}>
      <ScrollView
        keyboardShouldPersistTaps="handled"
        style={styles.ctnScrollMain}>
        <View style={styles.ctnView}>
          <TextCM style={styles.txtTitle}>{t('DC.ShareDocument.label')}</TextCM>
          <TextCM style={styles.txtNameDocument}>{data?.name}</TextCM>
          <FormProvider {...methods}>
            {isEditMode ? (
              renderIsEditMode()
            ) : (
              <View style={styles.groupTextField}>
                <Picker
                  value={methods.getValues('typeShare')}
                  label={t('DC.ShareDocument.chooseTypeShare')}
                  onPress={toggleModal('modalTypeShare')}
                  isRequired={true}
                />
                {showHide.showEmailField && (
                  <YupTextField
                    paramRef={ref}
                    isRequired={true}
                    controlName="email"
                    label={t('DC.ShareDocument.typeEmail')}
                    viewIconRight={
                      <View>
                        <TextCM style={styles.txtAdd}>{t('DC.TxtAdd')}</TextCM>
                      </View>
                    }
                    onPressIconRight={onPressAddEmail}
                  />
                )}
                {renderTag()}
                {showHide.showPhoneField && (
                  <YupTextField
                    controlName="phoneNumber"
                    label={t('NT.TxtPhone')}
                  />
                )}
                <Picker
                  value={methods.getValues('permission')?.label}
                  label={t('DC.ShareDocument.allowPermission')}
                  onPress={toggleModal('modalTypePermission')}
                />
                <View style={styles.viewPicDate}>
                  <PicDateView
                    label={t('DC.ShareDocument.effectFrom')}
                    date={fromDate}
                    maxDate={toDate}
                    onChangeDate={onChangeFromDate}
                  />
                  <PicDateView
                    label={t('DC.ShareDocument.effectTo')}
                    date={toDate}
                    minDate={fromDate}
                    onChangeDate={onChangeToDate}
                  />
                </View>
              </View>
            )}
          </FormProvider>
        </View>
        {renderListShare()}
      </ScrollView>
      <View>
        {isEditMode ? (
          <ButtonCM
            label={t('DC.TxtSaveChange')}
            onPress={onSubmitEdit}
            style={styles.btnStyle}
          />
        ) : (
          <ButtonCM
            disabled={listEmail.length === 0}
            label={t('DC.TxtSaveChange')}
            onPress={onSubmit}
            style={styles.btnStyle}
          />
        )}
      </View>
      {showModal.modalTypeShare && (
        <ModalTypeShare
          onClose={toggleModal('modalTypeShare')}
          isVisible={showModal.modalTypeShare}
          data={TYPE_OF_SHARE}
          onSubmit={onChooseTypeShare}
          currentSelected={methods.getValues('currentShareSelected') || []}
        />
      )}
      {showModal.modalTypePermission && (
        <ModalTypePermission
          onClose={toggleModal('modalTypePermission')}
          isVisible={showModal.modalTypePermission}
          data={LIST_PERMISSION}
          onSubmit={onChoosePermission}
          currentSelected={methods.getValues('permission')}
        />
      )}
    </View>
  );
};

export default ShareScreen;

type Props = {
  controlName: string;
  label: string;
  maxLength?: number;
  onPressIconRight?: () => void;
  viewIconRight?: React.ReactNode;
  isDisabled?: boolean;
  editable?: boolean;
  isRequired?: boolean;
  paramRef?: React.Ref<any>;
};

const YupTextField = ({
  controlName,
  label,
  maxLength,
  onPressIconRight,
  viewIconRight,
  isRequired,
  editable,
  paramRef,
}: Props) => {
  const {
    control,
    formState: {errors},
  } = useFormContext();

  return (
    <View>
      <Controller
        control={control}
        name={controlName}
        render={({field: {onChange, onBlur, value}}) => {
          return (
            <TextField
              ref={paramRef}
              label={label}
              placeholder={label}
              value={value}
              onBlur={onBlur}
              onChangeText={onChange}
              onIconPress={onPressIconRight}
              maxLength={maxLength}
              errorMessage={errors[controlName]?.message as string}
              viewIconRight={viewIconRight}
              inputContainerStyle={{backgroundColor: Color.White}}
              editable={editable}
              isRequired={isRequired}
              // styleIconRight={{width: 'auto'}}
            />
          );
        }}
      />
    </View>
  );
};
