import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity} from 'react-native';
import styles from './styles';

import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {IListUtility} from '../../helper';
import {isEmpty} from 'lodash';
import TextCM from '../../../../../components/Text';
import { View as ViewCM } from 'react-native';
import { IcBlackLeftArrow, IcCheckbox, IcCheckboxSelect } from '../../../../../assets/images';
import { SizeDP } from '../../../../../constants/Size';
import ButtonCM from '../../../../../components/Button';

type ModalConfigurationProp = {
  data: any;
  onClose: () => void;
  isVisible: boolean;
  onSubmit: (item: any) => void;
};

const ModalConfiguration = ({
  data,
  onClose,
  isVisible,
  onSubmit,
}: ModalConfigurationProp) => {
  let newData = data ? data : null;

  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [isCheckbox, setCheckbox] = useState<boolean>(false);

  useEffect(() => {
    setCheckbox(newData?.attrs?.confirm?.value === 'true' ? true : false);
  }, [newData]);

  const handleOnsubmit = () => {
    const initialData = {...newData};
    if (isEmpty(initialData.attrs)) {
      initialData.attrs = {
        confirm: {
          type: 'Boolean',
          validators: [{type: '', expression: ''}],
          value: `${isCheckbox}`,
        },
      };
      onSubmit(initialData);
    } else {
      onSubmit(newData);
    }
    onClose();
  };

  const onChoose = () => {
    const initialData = {...newData};
    if (isEmpty(initialData.attrs)) {
      initialData.attrs = {
        confirm: {
          type: 'Boolean',
          validators: [{type: '', expression: ''}],
          value: `${!isCheckbox}`,
        },
      };
      newData = initialData;
      setCheckbox(!isCheckbox);
    } else {
      newData.attrs.confirm.value = `${!isCheckbox}`;
      setCheckbox(!isCheckbox);
    }
  };
  const renderTitle = () => {
    switch (newData?.configType) {
      case IListUtility.personalConfirmSign:
        return (
          <TextCM style={styles.txtLabel}>
            {t('GS.defaultAgreeTermsElectronicSigning')}
          </TextCM>
        );
      case IListUtility.configDateTimeSignImage:
        return (
          <TextCM style={styles.txtLabel}>
            {t('GS.HidePhotoSignatureDateAndTimeDisplay')}
          </TextCM>
        );
      case IListUtility.configInternalFileAttach:
        return (
          <TextCM style={styles.txtLabel}>
            {t('GS.DefaultFileAttachmentsInternal')}
          </TextCM>
        );
      case IListUtility.personalReceiveMail:
      default:
        return (
          <TextCM style={styles.txtLabel}>
            {t('GS.defaultAgreeTermsElectronicSigning')}
          </TextCM>
        );
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('GS.config')}</TextCM>
            <ViewCM />
          </ViewCM>
          <ViewCM style={styles.viewBody}>
            {renderTitle()}
            <TouchableOpacity style={styles.ctnCheckbox} onPress={onChoose}>
              <ViewCM style={styles.ctnIcon}>
                {isCheckbox ? (
                  <IcCheckboxSelect width={SizeDP(24)} height={SizeDP(24)} />
                ) : (
                  <IcCheckbox width={SizeDP(24)} height={SizeDP(24)} />
                )}
              </ViewCM>
              {renderTitle()}
            </TouchableOpacity>
            <ButtonCM label={t('CM.TxtSave')} onPress={handleOnsubmit} />
          </ViewCM>
        </ViewCM>
      </ViewCM>
    </Modal>
  );
};

export default ModalConfiguration;
