import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Dimensions, Modal, TouchableOpacity} from 'react-native';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';

import YupTextField from '../YupTextField';
import {View as ViewCM} from 'react-native';
import {
  IconBlackCalendar,
  IconBlackLeftArrow,
  IconCheckedRadio,
  IconError,
  IconRadio,
} from '../../../../assets/images';
import TextCM from '../../../../components/Text';
import {SizeDP} from '../../../../constants/Size';
import {DateUtils, RegexUtils} from '../../../../utils';
import {useAppDispatch, useAppSelector} from '../../../../hook/useRedux';
import {accountActions, commonActions} from '../../../../redux/slices';
import {Controller, FormProvider, useForm} from 'react-hook-form';
import {yupResolver} from '@hookform/resolvers/yup';
import ButtonCM from '../../../../components/Button';
import ModalPicDate from '../../../../components/ModalPicDate';
import * as yup from 'yup';
import Toast from 'react-native-toast-message';
import { useAccountServices } from '../../../../hook/apiHook/useApi';

type ModalEditInfoProp = {
  onClose: () => void;
  isVisible: boolean;
};

type RadioButtonProps = {
  label: string;
  isSelected: boolean;
  onPress: () => void;
};

const MAX_LENGTH_DEFAULT = 255;
const MAX_LENGTH_NAME = 50;

const RadioButton = ({label, isSelected, onPress}: RadioButtonProps) => {
  return (
    <TouchableOpacity style={styles.ctnRadio} onPress={onPress}>
      <ViewCM style={styles.iconRadio}>
        {isSelected ? (
          <IconCheckedRadio width={SizeDP(24)} height={SizeDP(24)} />
        ) : (
          <IconRadio width={SizeDP(24)} height={SizeDP(24)} />
        )}
      </ViewCM>
      <TextCM style={styles.txtLabelRadio}>{label}</TextCM>
    </TouchableOpacity>
  );
};

const ModalEditInfo = ({onClose, isVisible}: ModalEditInfoProp) => {
  const accountServices = useAccountServices();
  const {t} = useTranslation();
  const schema = yup.object().shape({
    firstName: yup.string().trim().required(t('CM.RequireField')),
    lastName: yup.string().trim().required(t('CM.RequireField')),
    email: yup.string(),
    phoneNumber: yup
      .string()
      .trim()
      .required(t('CM.RequireField'))
      .matches(RegexUtils.REGEX_PHONE_NUMBER, t('AI.wrongPhoneNumber')),
    birthday: yup
      .string()
      .test('is-older-than-18', t('AI.under18'), function (value) {
        if (!value) return true;
        return DateUtils.checkIsOrderThen18(value);
      }),
  });
  const dispatch = useAppDispatch();
  const [isShowPicDate, setIsShowPicDate] = useState(false);
  const [heightScreen, setHeightScreen] = useState(
    Dimensions.get('window').height,
  );
  const user = useAppSelector(state => state.account.dataAccount);

  const {firstName, lastName, email, phone, dob, gender, address} = user;

  const insets = useSafeAreaInsets();

  const defaultValues: any = {
    firstName,
    lastName,
    email,
    phoneNumber: phone,
    birthday: dob ? dob?.toString() : '',
    gender,
    address,
  };

  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues,
  });

  useEffect(() => {
    methods.reset(defaultValues);
  }, [user, isVisible]);

  useEffect(() => {
    const sub = Dimensions.addEventListener('change', ({window}) => {
      setHeightScreen(window.height);
    });
    return () => sub.remove();
  }, []);

  const onPressSave = async () => {
    const {firstName, lastName, email, phoneNumber, birthday, gender, address} =
      methods.getValues();

    const body = {
      firstName: firstName.trim(),
      lastName: lastName.trim(),
      phone: phoneNumber,
      dob: birthday,
      gender,
      address: address?.trim(),
      login: email,
      authorities: user.authorities,
      langKey: user.langKey,
      activated: user.activated,
      imageUrl: user.imageUrl,
    };
    try {
      const res = await accountServices.postUpdateInfo(body);
      Toast.show({
        text1: t('AI.messageValidate.updateSuccess'),
        type: 'success',
      });
      dispatch(accountActions.fetchAccount());
      onClose();
    } catch (error) {
      Toast.show({
        text1: t('CM.TxtSystemError'),
        type: 'error',
      });
    }
  };

  const togglePicDate = () => {
    setIsShowPicDate(!isShowPicDate);
  };

  const onPicDate = async (date: Date) => {
    const birthdayString = DateUtils.convertToDateWithZeroTime(date);

    methods.setValue('birthday', birthdayString);
    try {
      await schema.validateAt('birthday', {birthday: birthdayString});
      methods.clearErrors('birthday');
    } catch (error) {
      if (error instanceof yup.ValidationError) {
        methods.setError('birthday', {type: 'manual', message: error.message});
      }
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM
          style={[
            styles.ctnContent,
            {
              paddingBottom: insets.bottom,
              height: (heightScreen / 4) * 3,
            },
          ]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IconBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>{t('AI.TxtDetailInfo')}</TextCM>
            <ViewCM />
          </ViewCM>
          <FormProvider {...methods}>
            <KeyboardAwareScrollView extraScrollHeight={SizeDP(20)}>
              <ViewCM style={styles.viewBody}>
                <YupTextField
                  controlName={'firstName'}
                  label={t('AI.TxtFirstName')}
                  isRequired
                  maxLength={MAX_LENGTH_NAME}
                />
                <YupTextField
                  controlName={'lastName'}
                  label={t('AI.TxtLastName')}
                  isRequired
                  maxLength={MAX_LENGTH_NAME}
                />
                <YupTextField
                  controlName={'email'}
                  label={t('AI.TxtEmail')}
                  isRequired
                  isDisabled
                  maxLength={MAX_LENGTH_DEFAULT}
                />
                <YupTextField
                  controlName={'phoneNumber'}
                  label={t('AI.TxtPhone')}
                  isRequired
                  maxLength={12}
                  keyboardType="phone-pad"
                />
                <Controller
                  control={methods.control}
                  name={'birthday'}
                  render={({field: {onChange, onBlur, value}}) => {
                    return (
                      <>
                        <TouchableOpacity
                          style={styles.btnPicBirthday}
                          onPress={togglePicDate}>
                          {value ? (
                            <ViewCM>
                              <TextCM style={styles.txtLabelBirthday}>
                                {t('AI.TxtBirthday')}
                              </TextCM>
                              <TextCM style={styles.txtBirthday}>
                                {DateUtils.convertDateToDDMMYYYY(
                                  new Date(value || ''),
                                )}
                              </TextCM>
                            </ViewCM>
                          ) : (
                            <TextCM style={styles.txtNoBirthday}>
                              {t('AI.TxtBirthday')}
                            </TextCM>
                          )}
                          <IconBlackCalendar
                            width={SizeDP(18)}
                            height={SizeDP(18)}
                          />
                        </TouchableOpacity>
                        {methods.formState.errors.birthday?.message && (
                          <ViewCM style={styles.errorContainer}>
                            <IconError width={SizeDP(16)} height={SizeDP(16)} />
                            <TextCM style={styles.errorText}>
                              {methods?.formState?.errors?.birthday?.message.toString()}
                            </TextCM>
                          </ViewCM>
                        )}
                      </>
                    );
                  }}
                />
                <Controller
                  control={methods.control}
                  name={'gender'}
                  render={({field: {onChange, onBlur, value}}) => {
                    return (
                      <ViewCM style={styles.viewGender}>
                        <RadioButton
                          label={t('AI.TxtMale')}
                          isSelected={value === 'M'}
                          onPress={() => methods.setValue('gender', 'M')}
                        />
                        <RadioButton
                          label={t('AI.TxtFemale')}
                          isSelected={value === 'F'}
                          onPress={() => methods.setValue('gender', 'F')}
                        />
                        <RadioButton
                          label={t('AI.TxtNo')}
                          isSelected={!value}
                          onPress={() => methods.setValue('gender', '')}
                        />
                      </ViewCM>
                    );
                  }}
                />
                <YupTextField
                  controlName={'address'}
                  label={t('AI.TxtAddress')}
                  maxLength={MAX_LENGTH_DEFAULT}
                  multiline
                />
              </ViewCM>
              <ViewCM style={styles.footer}>
                <ButtonCM
                  label={t('CM.TxtSave')}
                  onPress={() => {
                    methods.handleSubmit(onPressSave)();
                  }}
                />
              </ViewCM>
            </KeyboardAwareScrollView>
          </FormProvider>
        </ViewCM>
      </ViewCM>
      <ModalPicDate
        isVisible={isShowPicDate}
        onClose={togglePicDate}
        title={t('AI.TxtPicBirthday')}
        onSave={onPicDate}
        initDate={
          methods.getValues().birthday
            ? new Date(methods.getValues().birthday)
            : new Date()
        }
      />
    </Modal>
  );
};

export default ModalEditInfo;
