import {ScrollView, TouchableOpacity} from 'react-native';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import {isEmpty} from 'lodash';
import ModalHistoryDetail from '../ModalHistoryDetail';
import {useAppSelector} from '../../../../../hook/useRedux';
import {IHistoryConfigLogin} from '../../../../../services/interface';
import {useGeneralSettingServices} from '../../../../../hook/apiHook/useApi';
import TextCM from '../../../../../components/Text';
import {View as ViewCM} from 'react-native';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import { DateUtils } from '../../../../../utils';
import { useGeneralSettingFlowStore } from '../../../store/generalSettingFlowStore';


type Props = {
  isVisible: boolean;
  onClose: () => void;
};

const ModalHistory = ({isVisible, onClose}: Props) => {
  const {t} = useTranslation();
  const generalSettingServices = useGeneralSettingServices();
  // const {currentHistory} = useAppSelector(state => state.configSecurityLogin);
  const {currentHistory} = useGeneralSettingFlowStore()
  const [dataHistory, setDataHistory] = useState<any[]>([]);
  const [modalHistoryDetail, setModalHistoryDetail] = useState(false);
  const [currentItem, setCurrentItem] = useState<IHistoryConfigLogin | null>(
    null,
  );

  useEffect(() => {
    getData();
  }, [currentHistory]);

  const toggleModalHistoryDetail = (item?: IHistoryConfigLogin) => {
    setModalHistoryDetail(prevState => !prevState);
    setCurrentItem(item || null);
  };

  const getData = async () => {
    if (isEmpty(currentHistory)) return;
    const body = {resourceId: currentHistory.id, tableName: 'customer_logins'};
    const res = await generalSettingServices.getHistoryConfigLogin(body);
    setDataHistory(
      res.sort((a: any, b: any) => {
        const dateA = new Date(a.lastModifiedDate);
        const dateB = new Date(b.lastModifiedDate);
        return dateB.getTime() - dateA.getTime();
      }),
    );
  };

  const Content = () => {
    return (
      <ViewCM style={styles.container}>
        <TextCM style={styles.txtTitle}>{t('GS.history.infoHistory')}</TextCM>
        <ScrollView contentContainerStyle={styles.list}>
          {dataHistory.map(renderItem)}
        </ScrollView>
        <ButtonCM label={t('CM.BtnClose')} onPress={onClose} />
      </ViewCM>
    );
  };

  const renderItem = (item: IHistoryConfigLogin) => {
    return (
      <TouchableOpacity
        style={styles.viewItem}
        key={item.id}
        onPress={() => toggleModalHistoryDetail(item)}>
        <TextCM style={styles.txtName}>{item.createdBy}</TextCM>
        <ViewCM style={styles.viewValue}>
          <TextCM style={styles.txtLabel}>{t('GS.history.operation')}</TextCM>
          <TextCM
            style={[
              styles.txtStatus,
              item.method === 'POST' && styles.txtStatusCreate,
            ]}>
            {item.method === 'POST'
              ? t('GS.history.createNew')
              : t('GS.history.update')}
          </TextCM>
        </ViewCM>
        <ViewCM style={styles.viewValue}>
          <TextCM style={styles.txtLabel}>
            {t('GS.history.dateOperation')}
          </TextCM>
          <TextCM style={styles.txtDate}>
            {DateUtils.convertDateToDDMMYYYYhhmm(item.lastModifiedDate)}
          </TextCM>
        </ViewCM>
      </TouchableOpacity>
    );
  };

  return (
    <>
      <BottomSheetCM
        title={t('GS.history.history')}
        isVisible={isVisible}
        onClose={onClose}
        renderContent={<Content />}
      />
      <ModalHistoryDetail
        isVisible={modalHistoryDetail}
        onClose={() => toggleModalHistoryDetail()}
        data={currentItem}
      />
    </>
  );
};

export default ModalHistory;
