import {
  IconBlueFile,
  IconBlueLockFull,
  IconBlueFileCreate,
  IconBlueDateTime,
  IconBlueRoundDownload,
  IconBlueShare,
  IconBlueUnlockFull,
} from '../../../assets/images';
import {
  IDocumentTemplate,
  StatusDocumentTemplate,
} from '../../../model/interface/envelope.interface';
import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {BASE_URL} from '../../../services/httpClient';

export type ActionItem = {
  name: string;
  icon: React.ReactNode;
  type: ActionType;
};

export enum ActionType {
  open = 'open',
  disable = 'disable',
  createSingle = 'createSingle',
  createBatch = 'createBatch',
  validity = 'validity',
  history = 'history',
  download = 'download',
  share = 'share',
}

export const getListAction = (data: IDocumentTemplate) => {
  if (data.type === ItemType.MyDocumentTemplate) {
    if (data.status === StatusDocumentTemplate.published) {
      return [
        {
          name: 'DC.TxtOpenDocument',
          type: ActionType.open,
          icon: <IconBlueFile width={14} height={18} />,
        },
        {
          name: 'DC.DocumentTemplate.TxtUnpublished',
          type: ActionType.disable,
          icon: <IconBlueLockFull width={16} height={18} />,
        },
        {
          name: 'DC.DocumentTemplate.TxtCreateSingle',
          type: ActionType.createSingle,
          icon: <IconBlueFileCreate width={14} height={18} />,
        },
        // {
        //   name: ('DC.DocumentTemplate.TxtCreateBatch'),
        //   type: ActionType.createBatch,
        //   icon: <IconBlueCreateBatch width={(16)} height={(18)} />,
        // },
        {
          name: 'DC.DocumentTemplate.TxtValidity',
          type: ActionType.validity,
          icon: <IconBlueDateTime width={21} height={18} />,
        },
        {
          name: 'DC.DocumentTemplate.TxtHistory',
          type: ActionType.history,
          icon: <IconBlueFile width={14} height={18} />,
        },
        {
          name: 'DC.DocumentTemplate.TxtDownload',
          type: ActionType.download,
          icon: <IconBlueRoundDownload width={18} height={18} />,
        },
        {
          name: 'DC.DocumentTemplate.TxtShare',
          type: ActionType.share,
          icon: <IconBlueShare width={16} height={18} />,
        },
      ];
    }
    return [
      {
        name: 'DC.TxtOpenDocument',
        type: ActionType.open,
        icon: <IconBlueFile width={14} height={18} />,
      },
      {
        name: 'DC.DocumentTemplate.TxtPublished',
        type: ActionType.disable,
        icon: <IconBlueUnlockFull width={21} height={18} />,
      },

      {
        name: 'DC.DocumentTemplate.TxtDownload',
        type: ActionType.download,
        icon: <IconBlueRoundDownload width={18} height={18} />,
      },
      {
        name: 'DC.DocumentTemplate.TxtShare',
        type: ActionType.share,
        icon: <IconBlueShare width={16} height={18} />,
      },
    ];
  }
  if (data.status === StatusDocumentTemplate.published) {
    return [
      {
        name: 'DC.TxtOpenDocument',
        type: ActionType.open,
        icon: <IconBlueFile width={14} height={18} />,
      },
      {
        name: 'DC.DocumentTemplate.TxtCreateSingle',
        type: ActionType.createSingle,
        icon: <IconBlueFileCreate width={14} height={18} />,
      },
      // {
      //   name: ('DC.DocumentTemplate.TxtCreateBatch'),
      //   type: ActionType.createBatch,
      //   icon: <IconBlueCreateBatch width={(16)} height={(18)} />,
      // },
      {
        name: 'DC.DocumentTemplate.TxtHistory',
        type: ActionType.history,
        icon: <IconBlueFile width={14} height={18} />,
      },
      {
        name: 'DC.TxtDownload',
        type: ActionType.download,
        icon: <IconBlueRoundDownload width={18} height={18} />,
      },
    ];
  } else {
    return [
      {
        name: 'DC.TxtOpenDocument',
        type: ActionType.open,
        icon: <IconBlueFile width={14} height={18} />,
      },
      {
        name: 'DC.TxtDownload',
        type: ActionType.download,
        icon: <IconBlueRoundDownload width={18} height={18} />,
      },
    ];
  }
};

export const handleDownloadUrl = (id: string) => {
  return `${BASE_URL}/services/envelope/api/envelope/${id}/doc/contentall`;
};
export const handleDownloadUrlDocumentTemplate = (id: string) => {
  return `${BASE_URL}/services/envelope/api/template/${id}/doc/contentall`;
};
