import {ActionTypeExpensesDefault} from '../../../services/interface';
import {IGeneralSetting} from '../general-setting/helper';

export const getTitle = (type: IGeneralSetting, t: any): string => {
  switch (type) {
    case IGeneralSetting.integration:
      return t('GS.expensesDefault.title', {
        name: t('GS.integration'),
      });
    case IGeneralSetting.notification:
      return t('GS.expensesDefault.title', {
        name: t('GS.notification'),
      });
    case IGeneralSetting.signature:
      return t('GS.expensesDefault.title', {
        name: t('GS.signature'),
      });
    default:
      return '';
  }
};

export const getNameType = (type: IGeneralSetting): string => {
  switch (type) {
    case IGeneralSetting.integration:
      return 'GS.integration';
    case IGeneralSetting.notification:
      return 'GS.notification';
    case IGeneralSetting.signature:
      return 'GS.signature';
    default:
      return '';
  }
};

export const getType = (
  type: IGeneralSetting,
): ActionTypeExpensesDefault | string => {
  switch (type) {
    case IGeneralSetting.integration:
      return ActionTypeExpensesDefault.integrate;
    case IGeneralSetting.notification:
      return ActionTypeExpensesDefault.notify;
    case IGeneralSetting.signature:
      return ActionTypeExpensesDefault.sign;
    default:
      return '';
  }
};
