import {View, Text, FlatList, TouchableOpacity} from 'react-native';
import React, {useEffect, useState} from 'react';

import {SafeAreaView} from 'react-native-safe-area-context';
import styles from './styles';
import {useTranslation} from 'react-i18next';

import {isEmpty} from 'lodash';
import ModalCreateConfig from './components/ModalCreateConfig';
import ModalHistory from './components/ModalHistory';
import {useAppDispatch, useAppSelector} from '../../../hook/useRedux';
import {IConfigSecurityLogin} from '../../../services/interface';
import {useGeneralSettingServices} from '../../../hook/apiHook/useApi';
import TextCM from '../../../components/Text';
import {View as ViewCM} from 'react-native';
import SwitchCM from '../../../components/Switch';
import {
  IconBluePen,
  IconBlueSignin,
  IconRedConfirmTrash,
  IconRedDelete,
} from '../../../assets/images';
import {SizeDP} from '../../../constants/Size';
import Toast from 'react-native-toast-message';
import HeaderCM from '../../../components/Header/HeaderCM';
import ButtonCM from '../../../components/Button';
import ModalConfirm from '../../../components/ModalConfirm';
import {useGeneralSettingFlowStore} from '../store/generalSettingFlowStore';

const ConfigSecurityLogin = () => {
  const {t} = useTranslation();
  const generalSettingServices = useGeneralSettingServices();
  const account = useAppSelector(state => state.account.dataAccount);
  const {listData, setListData, setCurrentEdit, setCurrentHistory} =
    useGeneralSettingFlowStore();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [modalConfirmDelete, setModalConfirmDelete] = useState(false);
  const [currentDelete, setCurrentDelete] = useState<IConfigSecurityLogin>();
  const [modalAdd, setModalAdd] = useState(false);
  const [modalHistory, setModalHistory] = useState(false);


  useEffect(() => {
    getData();
  }, [account.custId]);

  const getData = async () => {
    const res = await generalSettingServices.listConfigSecurityLogin(
      account.custId as number,
    );
    setListData(res);
  };

  const toggleModalDelete = () => {
    setModalConfirmDelete(!modalConfirmDelete);
  };

  const toggleModalAdd = () => {
    setModalAdd(!modalAdd);
  };

  const renderItem = ({item}: {item: IConfigSecurityLogin}) => {
    return (
      <TouchableOpacity style={styles.item} onPress={() => onShowHistory(item)}>
        <TextCM style={styles.txtName}>{item.name}</TextCM>
        <TextCM style={styles.txtType}>{item.type}</TextCM>
        <ViewCM style={styles.viewIconFooter}>
          <SwitchCM
            isEnabled={item.active}
            onPress={() => {
              toggleActive(item);
            }}
          />
          <ViewCM style={styles.viewAction}>
            <TouchableOpacity
              style={styles.btnDelete}
              onPress={() => {
                toggleModalDelete();
                setCurrentDelete(item);
              }}>
              <IconRedDelete width={SizeDP(14)} height={SizeDP(14)} />
            </TouchableOpacity>
            <TouchableOpacity
              style={styles.btnEdit}
              onPress={() => {
                setCurrentEdit(item);
                // dispatch(configSecurityLoginActions.updateCurrentEdit(item));
                toggleModalAdd();
              }}>
              <IconBluePen width={SizeDP(14)} height={SizeDP(14)} />
            </TouchableOpacity>
          </ViewCM>
        </ViewCM>
      </TouchableOpacity>
    );
  };

  const onShowHistory = (item: IConfigSecurityLogin) => {
    setCurrentHistory(item)
    // dispatch(configSecurityLoginActions.currentHistory(item));
    toggleModalHistory();
  };

  const toggleModalHistory = () => {
    setModalHistory(!modalHistory);
  };

  const toggleActive = async (item: IConfigSecurityLogin) => {
    const newBody = {
      ...item,
      active: !item.active,
    };
    try {
      await generalSettingServices.updateConfigSecurityLogin(newBody);
      Toast.show({
        text1: t('GS.configSecurityLogin.TxtCreateSuccess'),
        type: 'success',
      });
      getData();
    } catch (error) {}
  };

  const onDeleteItem = async () => {
    toggleModalDelete();
    if (isEmpty(currentDelete)) {
      return;
    }
    try {
      await generalSettingServices.deleteConfigSecurityLogin(currentDelete.id);
      getData();
      Toast.show({
        type: 'success',
        text1: t('GS.configSecurityLogin.TxtDeleteSuccess'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    }
    setCurrentDelete(undefined);
  };

  const onRefresh = () => {
    setIsRefreshing(true);
    getData().finally(() => setIsRefreshing(false));
  };

  const renderIconDelete = () => (
    <IconRedConfirmTrash width={SizeDP(80)} height={SizeDP(80)} />
  );

  const onPressAdd = () => {
    setCurrentEdit(null)
    toggleModalAdd();
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM title={`${t('GS.configSecurity')} - ${t('GS.login')}`} />
      <ViewCM style={styles.body}>
        <ViewCM style={styles.content}>
          <FlatList
            data={listData}
            refreshing={isRefreshing}
            onRefresh={onRefresh}
            ListHeaderComponent={
              <ViewCM style={styles.header}>
                <IconBlueSignin width={SizeDP(23)} height={SizeDP(18)} />
                <TextCM style={styles.txtTitle}>{t('GS.login')}</TextCM>
              </ViewCM>
            }
            keyExtractor={item => item.id.toString()}
            renderItem={renderItem}
            contentContainerStyle={styles.ctnFlatList}
            showsVerticalScrollIndicator={false}
            ListEmptyComponent={<Nodata />}
          />
        </ViewCM>
        {listData.length < 5 && (
          <ButtonCM
            onPress={toggleModalAdd}
            label={t('GS.configSecurityLogin.TxtCreate')}
          />
        )}
      </ViewCM>
      <ModalConfirm
        title={t('GS.configSecurityLogin.TxtTitleDelete')}
        content={t('GS.configSecurityLogin.TxtDesDelete')}
        labelConfirm={t('CM.BtnClear')}
        renderIcon={renderIconDelete}
        onConfirm={onDeleteItem}
        isVisible={modalConfirmDelete}
        onClose={toggleModalDelete}
      />
      {modalAdd && (
        <ModalCreateConfig
          isVisible={modalAdd}
          onClose={onPressAdd}
          onSuccess={getData}
        />
      )}
      {modalHistory && (
        <ModalHistory isVisible={modalHistory} onClose={toggleModalHistory} />
      )}
    </SafeAreaView>
  );
};

export default ConfigSecurityLogin;

const Nodata = () => {
  const {t} = useTranslation();
  return (
    <TextCM style={styles.txtNoData}>
      {t('GS.configSecurityLogin.TxtNoData')}
    </TextCM>
  );
};
